INSERT INTO m228_art VALUES
(0,0,$m228$الديباجة$m228$,$m228$قانون رقم 203 لسنة 1991 بتاريخ 19/06/1991 بشأن اصدار قانون شركات قطاع الاعمال العام$m228$,'cf2820cad4cf13bbab3f5cfb51b20149'),
(1,-1,$m228$المادة الأولى إصدار$m228$,$m228$يعمل في شأن قطاع الأعمال العام بأحكام القانون المرافق، و يقصد بهذا القطاع الشركات القابضة و الشركات التابعة لها الخاضعة لأحكام هذا القانون، وتتخذ هذه الشركات بنوعيها شكل شركات المساهمة و يسرى عليها فيما لم يرد بشأنه نص خاص في هذا القانون و لا يتعارض مع أحكامه نصوص قانون شركات المساهمة و شركات التوصية بالأسهم و الشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981.
و لا تسرى أحكام قانون هيئات القطاع العام و شركاته الصادر بالقانون رقم 97 لسنة 1983 على الشركات المشار إليها.$m228$,'4ec9f5a5b2472202c97a96542b37b720'),
(1,0,$m228$المادة 1$m228$,$m228$يصدر بتأسيس الشركة القابضة قرار من رئيس مجلس الوزراء بناء على اقتراح الوزير المختص و يكون رأسمالها مملوكا بالكامل للدولة أو للأشخاص الاعتبارية العامة و تثبت لها الشخصية الاعتبارية من تاريخ قيدها في السجل التجاري.
و تأخذ الشركة القابضة شكل شركة المساهمة و تعتبر من أشخاص القانون الخاص و يحددالقرار الصادر بتأسيسها اسمها و مركزها الرئيسى و مدتها و الغرض الذي أنشئت من أجله و رأس مالها.
و ينشر القرار الصادر بتأسيس الشركة مع نظامها الأساسي على نفقتها في الوقائع المصرية و تقيد الشركة في السجل التجارى.$m228$,'cfb586ace0a30f682d2b79b5b5c59264'),
(2,-1,$m228$المادة الثانية إصدار$m228$,$m228$تحل الشركات القابضة محل هيئات القطاع العام الخاضعة لأحكام القانون رقم 97 لسنة 1983 المشار إليه كما تحل الشركات التابعة محل الشركات التى تشرف عليها هذه الهيئات وذلك اعتبارا من تاريخ العمل بهذا القانون ودون حاجة الى أى اجراء أخر.
و تنتقل إلي الشركات القابضة و الشركات التابعة لها بحسب الأحوال كافة ما لهيئات القطاع العام القطاع العام و شركاته الملغاة من حقوق بما فيها حقوق الانتفاع والإيجار كما تتحمل جميع التزاماتها وتسأل مسئولية كاملة عنها.
و ينشر النظام الأساسي لكل شركة من الشركات القابضة والتابعة على نفقتها في الوقائع المصرية و تقيد في السجل التجارى.$m228$,'33c87ea180f1a8b2f74f337c19a53620'),
(2,0,$m228$المادة 2$m228$,$m228$تتولى الشركة القابضة من خلال الشركات التابعة لها إستثمار أموالها كما يكون لها عند الاقتضاء أن تقوم بالإستثمار بنفسها.
و تتولى الشركة القابضة في مجال نشاطها و من خلال الشركات التابعة لها المشاركة في تنمية الاقتصاد القومى في إطار السياسية العامة للدولة.
وللشركة أيضا في سبيل تحقيق أغراضها القيام بالأعمال الآتية:
1 - تأسيس شركات مساهمة بمفردها أو بأالشتراك مع الأشخاص الاعتبارية العامة أو الخاصة أو الأفرد
2 - شراء أسهم شركات المساهمة أو بيعها أو المساهمة في رأسمالها.
3 - تكوين وإدارة محفظة الأوراق المالية للشركة بما تتضمنه من أسهم و صكوك تمويل و سندات و أية أدوات أو أصول مالية أخرى.
4 - إجراء جميع التصرفات التى من شأنها أن تساعد في تحقيق كل أو بعض أغراضها.$m228$,'9be2261993f967010c35a3f48bea8dbd'),
(3,-1,$m228$المادة الثالثة إصدار$m228$,$m228$تشكل مجالس إدارة الشركات القابضة و الشركات التابعة و فق أحكام القانون المرافق خلال ستة أشهر من تاريخ العمل به.
و يتولى رؤساء و أعضاء مجالس الإدارة الحاليون لكل من هيئات القطاع العام وشركاته بحسب الأحوال إدارة الشركات المذكورة و ذلك حتى يتم تشكيل مجالس الإدارة الجديدة لها.$m228$,'ce68988e7e359033e8d2613f1bb8a380'),
(3,0,$m228$المادة 3$m228$,$m228$يتولى إدارة الشركة القابضة مجلس إدارة يصدر بتشكيله قرار من الجمعية العامة بناء على اقتراح رئيسها لمدة ثلاث سنوات قابلة للتجديد على أن يعكس التشكيل حقوق الملكية بالشركة، ويتكون من عدد من الأعضاء يحدده النظام الأساسي لا يقل عن خمسة ولا يزيد على تسعة، ويشكل على الوجه الآتي:
1 - رئيس غير تنفيذي لمجلس إدارة الشركة.
2 - أعضاء يمثلون المساهمين بالشركة وفقا لهيكل ملكية الشركة بمراعاة قواعد التمثيل النسبي، منهم عضو يمثل وزارة المالية يرشحه وزير المالية، وتعينهم الجمعية العامة، دون الإخلال بحق الشخص الاعتباري المساهم في الشركة في تغيير ممثليه خلال مدة المجلس.
3 - ممثل عن الاتحاد النقابي العمالي الأكثر تمثيلا يختاره مجلس إدارة الاتحاد بمراعاة طبيعة نشاط الشركة.
ويجوز أن يتضمن النظام الأساسي للشركة أعضاء مستقلين إضافيين من ذوي الخبرة بمجلس الإدارة لا يزيد عددهم على عضوين تختارهم الجمعية العامة بناء علي ترشيح لوزير المختص.
ولا يعتبر رئيس وأعضاء مجلس الإدارة من العاملين بالشركة.
ويحدد القرار الصادر بتشكيل المجلس العضو المنتدب التنفيذي وغيره من الأعضاء المنتدبين للإدارة.
وتحدد الجمعية العامة سنويا من يتقاضاه كل من رئيس وأعضاء المجلس المشار إليهم من بدلات الحضور والانتقال للجلسات، وكذا ما يتقاضاه رئيس المجلس والأعضاء المنتدبون من رواتب والمكافأة السنوية التي يستحقها مجلس الإدارة بمراعاة نص المادة (24) من هذا القانون، كما تحدد الجمعية العامة المزايا الأخرى للأعضاء المنتدبين للإدارة بما في ذلك التأمين الطبي ووسائل الانتقال.
وفي جميع الأحوال، لا يجوز أن يزيد بدل الحضور والانتقال لرئيس وأعضاء المجلس على الحد الذي يصدر به قرار من رئيس مجلس الوزراء.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'9d8ca178334dff647034bac02f4a95a2'),
(4,-1,$m228$المادة الرابعة إصدار$m228$,$m228$ينقل العاملون بكل من هيئات القطاع العام و شركاته الموجودون بالخدمة في تاريخ العمل بهذا القانون إلى الشركات القابضة أو الشركات التابعة لها بذات أوضاعهم الوظيفية وأجورهم وبدالتهم واجازاتهم ومزاياهم النقدية والعينية والتعويضات.
و تستمر معاملة هؤلاء العاملين بجميع الأنظمة والقواعد التى تنظم شئونهم الوظيفية وذلك إلى أن تصدر لوائح أنظمة العاملين بالشركات المنقولين إليها طبقا لأحكام القانون المرافق خلال سنة من التاريخ المذكور.
و يحتفظ العامل المنقول بصفة شخصية بما يحصل عليه من أجور وبدلات و إجازات و مزايا نقدية وعينية و تعويضات و لو كانت تزيد على ما يستحقه طبقا لهذه اللوائح دون أن يؤثر ذلك على ما يستحقه مستقبلا من أية علاوات أو مزايا.$m228$,'c59a794041f42100f664038e8c8a3157'),
(4,0,$m228$المادة 4$m228$,$m228$لا يجوز أن يكون رئيسا أو عضوا بمجلس إدارة الشركة من حكم عليه بعقوبة جناية أو بعقوبة مقيدة للحرية في جريمة مخلة بالشرف أو الأمانة أو تفالس أو بعقوبة من العقوبات المنصوص عليها في المواد (49 و50 و51) من هذا القانون.$m228$,'7d4df4734d6b556741e9e20aeaa0e6ab'),
(5,-1,$m228$المادة الخامسة إصدار$m228$,$m228$مع عدم الإخلال بما ورد في شأنه نص خاص في هذا القانون أو في القانون المرافق لا يسري نظام العاملين بالقطاع العام الصادر بالقانون رقم 48 لسنة 1978 على العاملين بالشركات الخاضعة لحكام القانون المرافق و ذلك اعتبارا من تاريخ العمل باللوائح المشار إليها.$m228$,'1b8c695bfeae0009a13976f49ac9824f'),
(5,0,$m228$المادة 5$m228$,$m228$يكون للجمعية العامة العادية للشركة عند مناقشتها لنتائج أعمال الشركة السنوية تغيير رئيس وأعضاء مجلس إدارة الشركة كلهم أو بعضهم أثناء مدة العضوية، وفي حلة تغيير المجلس بأكمله يجوز للجمعية العامة تعيين مفوض لإدارة الشركة بصفة مؤقتة ولمدة لا تجاوز ثلاثة أشهر لحين تشكيل مجلس إدارة جديد طبقا لأحكام هذا القانون.
ويسري حكم هذه الفترة على الشركات التابعة الخاضعة لأحكام هذا القانون.
كما لا يجوز تجديد تعيين رئيس و أعضاء مجلس إدارة الشركة إذا لم تحقق الشركة الأهداف المحددة لها خلال مدة العضوية.
*الفقرة الأولى معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'864a425d8c0f2f39e8300e16ba87babd'),
(6,-1,$m228$المادة السادسة إصدار$m228$,$m228$تستمر محاكم مجلس الدولة في نظر الدعاوى و الطعون الآتية التى رفعت إليها إلي أن يتم الفصل فيها بحكم بات و فقا للقواعد المعمول بها حاليا و ذلك دون حاجة لي إجراء آخر.
أولا - الدعاوى التأديبية و طعون الجزاءات التأديبية و غيرها من الدعاوى المتعلقة بالعاملين بالشركات الخاضعة لأحكام هذا القانون متى كانت قد رفعت قبل العمل باللوائح المنصوص عليها في المادة السابقة.
ثانيا - الدعاوي و الطعون الأخري التى تكون تلك الشركات طرفا فيها متى كانت قد رفعت قبل العمل بهذا القانون.$m228$,'32458919648685cfe104b80d19513c27'),
(6,0,$m228$المادة 6$m228$,$m228$لمجلس إدارة الشركة مباشرة كل السلطات اللازمة لتصريف أمور الشركة والقيام بكافة الأعمال اللازمة لتحقيق الغرض الذي أنشئت من أجله و ذلك فيما عدا ما تختص به الجمعية العامة للشركة و لمجلس الإدارة في سبيل ذلك على الأخص ما يأتى:
1 - وضع السياسات العامة و تحديد الوسائل اللازمة لتحقيقها.
2 - إدارة محفظة الأوراق المالية للشركة بيعا و شراء مما تتضمنه من أسهم و صكوك تمويل و سندات و أية أدوات و أصول مالية أخرى.
3 - إقتراح تأسيس شركات مساهمة تؤسسها الشركة بمفردها أوبالإشتراك مع الأشخاص الاعتبارية العامة أو الخاصة أو الأفراد.
4 - شراء أسهم شركات المساهمة أو بيعها أو المساهمة في رأس مالها.
5 - القيام بكافة الأعمال اللازمة لتصحيح الهياكل التمويلية و مسار الشركات المتعثرة التابعة لها و تعظيم ربحية هذه الشركات و ترشيد التكلفة.
6 - إقرار مشروع الميزانية و الحسابات الختامية تمهيدا لعرضها على الجمعية العامة للشركة.
7 - و ضع معايير الأداء و تقيمها و فحص التقاير التى تقدم عن سير العمل بالشركة.
8 - اعتماد الهيكل التنظيمى للشركة وو ضع اللوائح الداخلية المتعلقة بالنواحى المالية و الإدارية و الفنية وغيرها.
9 - ما يرى رئيس الجمعية العامة أو رئيس مجلس الإدارة عرضه على المجلس.$m228$,'eae1ef4731df93cd2d19a1699e88c102'),
(6,1,$m228$المادة 6 مكرراً$m228$,$m228$يضع مجلس إدارة الشركة القابضة الضوابط الواجب الالتزام بها لقيام الشركة القابضة أو شركاتها التابعة بتأسيس أو المشاركة في تأسيس الشركات الأخرى، ويتم اعتمادها من الوزير المختص، على أن تتضمن هذه الضوابط على الأخص ما يأتي:
1 - وجود جدوى اقتصادية من إنشاء الشركة الجديدة، أو المساهمة فيها.
2 - عدم وجود شركة تابعة أخرى يمكن لها القيام بالنشاط المطلوب تأسيس شركة لممارسته.
3 - أن تكون الجمعية العامة للشركة أو مجلس إدارتها هو السلطة المختص بالموافقة على إنشاء الشركة الجديدة أو المساهمة فيها، وفق لما يحده النظام الأساسي للشركة.
وعلى الشركة القابضة وضع نظام لمتابعة أداء الشركات التي تساهم فيها الشركة القابضة وشركاتها التابعة يتضمن على الأخص التقارير الدورية لمتابعة أداء هذه الشركات والرقابة عليها، وقواعد اختيار ممثلي الشركة القابضة أو التابعة في عضوية مجلس إدارات هذه الشركات، والتأكد من اتباع الإجراءات الواجبة عند التخارج من هذه الشركات، وذلك كله وفقا للقواعد التي يضعها الوزير المختص.
*مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'887b67ca06fbe94f6794f25fb5258a9a'),
(7,-1,$m228$المادة السابعة إصدار$m228$,$m228$لا يجوز حرمان الشركات الخاضعة لأحكام هذا القانون من أية مزايا أو تحميلها بأية أعباء تخل بالمساواة بينها و بين شركات المساهمة الخاضعة لأحكام القانون رقم 159 لسنة 1981 المشارإ ليها التى تعمل في ذات النشاط و يلغى البند (1) من المادة السادسة من القانون رقم 66 لسنة 1971 بإنشاء هيئة عامة باسم بنك ناصر الاجتماعي كما تلغى عبارة و في حدود الموازنة النقدية السارية الواردة في الفقرة الأولي من المادة (1) من القانون رقم 118 لسنة 1975 في شأن الاستيراد و التصدير.$m228$,'715959d16c7a0646d080a562f59767f6'),
(7,0,$m228$المادة 7$m228$,$m228$يجتمع مجلس الإدارة مرة على الأقل كل شهر بدعوة من رئيسه و في حالة غيابه يندب رئيس الجمعية العامة من بين أعضاء المجلس من يرأس الاجتماع.
و لا يكون انعقاد المجلس صحيحا إلا بحضور أغلبية الأعضاء و تصدر قراراته بأغلبية أصوات الحاضرين وعند التساوى يرجح الجانب الذي منه الرئيس.
وللمجلس أن يدعو لحضور اجتماعاته من يرى الإستعانة بهم من ذوى الخبرة من العاملين بالشركة أو غيرهم دون ان يكون لهم صوت معدود فيما يتخذه المجلس من قرارات.
و يجوز للمجلس أن يشكل من بين أعضائه لجنة أو لجانا يعهد إليها ببعض إختصاصاته كما يجوز له أن يعهد إلي رئيس مجلس الإدارة أو أحد المديرين في القيام بمهمة محددة على أن يعرض على المجلس تقريرا بما قام به من أعمال.$m228$,'e387433c2f0b253a928bfd0d46113fb1'),
(8,-1,$m228$المادة الثامنة إصدار$m228$,$m228$يصدر رئيس الجمهورية قرار بتحديد الوزير المختص (*) في تطبيق أحكام هذا القانون وعليه أن يقدم إلي مجلس الوزراء تقارير دورية و فقا لما تحدده اللائحة التنفيذية عن نتائج أعمال الشركات الخاضعة لأحكام هذاالقانون.
(*) انظر قرار رئيس جمهورية مصر العربية رقم 296 لسنة 1991 ص 115 من هذاالكتاب$m228$,'ab7dc66334b814eb67de063c086fa6f9'),
(8,0,$m228$المادة 8$m228$,$m228$يمثل الشركة أمام القضاء وفي صالتها بالغير رئيس مجلس الإدارة أو العضو المنتدب التنفيذي بحسب النظام الأساسي للشركة، ويختص العضو المنتدب التنفيذي بما يأتي:
1 - تنفيذ قرارات مجلس الإدارة.
2 - إدارة الشركة وتصريف شئونها.
وله أن يفوض واحدا أو أكثر من أعضاء مجلس الإدارة في بعض اختصاصاته.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'49e1723657e8cc8812e45d9e229b8b9e'),
(9,-1,$m228$المادة التاسعة إصدار$m228$,$m228$يجوز بقرار من رئيس الجمهورية بعد موافقة مجلس الوزراء تحويل إحدي الهيئات الاقتصادية أو المؤسسات العامة أو شركات القطاع العام المقرر لها أنظمة خاصة إلي شركة قابضة أو شركة تابعة تخضع لحكام هذا القانون.$m228$,'a5170f1b0c8499933bfbcda3978c3878'),
(9,0,$m228$المادة 9$m228$,$m228$تتكون الجمعية العامة للشركة على النحو الآتي:
1 - الوزير المختص رئيسا.
2 - أعضاء من ذوي الخبرة في مجال الأنشطة التي تقوم بها الشركة القابضة وشركاتها التابعة لا يقل عددهم عن اثني عشر ولا يزيد على أربعة عشرة من بينهم ممثل واحد على الأقل يرشحه الاتحاد النقابي العمالي الأكثر تمثيلا وممثل عن وزارة المالية برشحه وزير المالية يصدر باختيارهم قرار من رئيس مجلس الوزراء، ويحدد القرار ما يتقاضونه من بدل الحضور والانتقال وفقا للقواعد التي تحددها اللائحة التنفيذية لهذا القانون.
ويحضر اجتماعات الجمعية العامة رئيس وأعضاء مجلس إدارة الشركة، ومراقبو الحسابات بالجهاز المركزي للمحاسبات، ومراقب الحسابات المعين من الجمعية العامة للشركة إن وجد، دون أن يكون لهم صوت معدود.ويجوز للوزير المختص تفويض غيره في حضور الجمعية العامة.
وتصدر قرارات الجمعية العامة بأغلبية أصوات الحاضرين بالاجتماع فيما عدا الأحوال التي تتطلب فيها اللائحة التنفيذية لهذا القانون أو النظام الأساسي للشركة أغلبية خاصة.
وتبين اللائحة التنفيذية لهذا القانون شروط صحة انعقاد الجمعية العامة ونظام التصويت على المسائل المعروضة عليها بحسب ما إذا كانت الجمعية العامة منعقدة في اجتماع عادي أو غير عادي.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'561e2972b4edf07dc42e4488e0571ded'),
(10,-1,$m228$المادة العاشرة إصدار$m228$,$m228$لا تخل أحكام المادة الثامنة من هذا القانون بالإختصاصات والسلطات الإدارية والتنفيذية المقررة للوزراء بمقتضى القوانين و اللوائح والقرارات الجمهورية.$m228$,'247ba8457135641e589c6ee488df15e3'),
(10,0,$m228$المادة 10$m228$,$m228$مع مراعاة أحكام هذا القانون و لائحته التنفيذية و النظام الساسي للشركة تختص الجمعية العادية العادية بما يأتى:
(أ) التصديق على تقرير مجلس الإدارة عن نشاط الشركة و النظر في إخلاء المجلس من المسئولية عن الفترة المقدم عنها التقرير.
(ب) التصديق على الميزانية والحسابات الختامية للشركة.
(ج) الموافقة على استمرار رئيس و أعضاء مجلس الإدارة لمدة تالية أو عزلهم.
ويكون التصويت على ذلك بطريق الاقتراع السري.
(د) الموافقة على توزيع الأرباح.
(ه) كل ما يرى رئيس الجمعية العامة أو مجلس الإدارة عرضه عليها.
و لا يجوز التصرف بالبيع في أصل من خطوط الإنتاج الرئيسية إلا بعد موافقة الجمعية العامة و طبقا للقواعد التى تحددها اللائحة التنفيذية.$m228$,'2d0f00bcfd677d2455768e1303877122'),
(11,-1,$m228$المادة الحادية عشرة إصدار$m228$,$m228$يختص مجلس الدولة دون غيره بمراجعة نموذج العقد الأبتدائى و نماذج النظام الأساسي للشركات الخاضعة لأحكام هذا القانون.
ولشركات المشارإليها أن تطلب إلي مجلس الدولة عن طريق الوزير المختص إباء الرأي مسببا في المسائل المتعلقة بشئون العاملين فيها أو أعضاء مجلس إدارتها أو بغير ذلك من المسائل التى تتعلق بأي شأن آخر من شئونها.$m228$,'5f649e7ddad0042f3804625dc2e5824a'),
(11,0,$m228$المادة 11$m228$,$m228$لا يجوز تعديل نظام الشركة إلا بعد موافقة الجمعية العامة غير العادية وفقا لأحكام اللائحة التنفيذية.$m228$,'6e4eb2c809cec6129f7907faeec623a0'),
(12,-1,$m228$المادة الثانية عشرة إصدار$m228$,$m228$يصدر رئيس مجلس الوزراء اللائحة التنفيذية للقانون المرافق خلال ثلاثة أشهر من تاريخ العمل بهذا القانون(*).
كما يصدر نموذج العقد الأبتدائي و نموذج النظام الأساسي للشركات الخاضعة لأحكام هذا القانون و ذلك خلال ستة أشهر من تاريخ العمل باللائحة التنفيذية (-) و يجوز أن تتعدد نماذج النظم الأساسية للشركات بحسب طبيعة أنشطتها.
(*) صدر قرار رئيس مجلس الوزراء رقم 1590 لسنة 1991 بغصدار اللائحة التنفيذية المشار إليها و نشر بالجريدة الرسمية –عدد رقم 44 تابع في 31/10/1991 و أعدبه كتابة و يرجع إليه إذا لزم الأمر.
(-) صدر قرار رئيس مجلس الوزراء رقم 1900 لسنة 1991 بإصدار نماذج العقود الإبتدائية و الأنظمة الأساسية لشركات قطاع الأعمال العام ونشر بالجريدة الرسمية –عدد(2 تابع) في 1992/9/1 و أعد به كتابة إذا لزم الأمر.
()-$m228$,'85fe4a922a7f197829f0bc7bde52adfb'),
(12,0,$m228$المادة 12$m228$,$m228$يحدد النظام الأساسي بداية ونهاية السنة المالية للشركة.
و تعتبر أموال الشركةمن الأموال المملوكة للدولة ملكية خاصة و تودع الشركة مواردها بالنقد المحلي و الأجنبي في حساب مصرفي بالبنك المركزى أو أحد البنوك التجارية.$m228$,'e9f6b94c292f077f2c52a5129738c3ac'),
(13,-1,$m228$المادة الثالثة عشرة إصدار$m228$,$m228$ينشر هذا القانون في الجريدة الرسمية، و يعمل به بعد ثلاثين يوما من تاريخ نشره.
يبصم هذا القانون بخاتم الدولة، و ينفذ كقانون من قوانينها.
صدر برياسة الجمهورية في 7 ذي الحجة سنة 1411. (19 يونية سنة 1991 م) حسنى مبارك$m228$,'87a7dddee2f5a97c07b384ab5fd8379b'),
(13,0,$m228$المادة 13$m228$,$m228$تعد الشركة القابضة قوائم مالية مجمعة تعرض اصول و التزامات و حقوق المساهمين و إيردات و مصروفات و استخدامات الشركة القابضة و الشركات التابعة لها وفقا للأوضاع و الشروط و البيانات التى تحددها اللائحة التنفيذية$m228$,'9b27cceebf26517721d65c75af9eabf1'),
(14,0,$m228$المادة 14$m228$,$m228$تحدد الأرباح الصافية للشركة و يتم توزيعها بقرار من الجمعية العامة طبقا لأحكام هذا القانون ولائحته التنفيذية.
و يؤول نصيب الدولة في هذه الأرباح إلي الخزانة العامة.
(*) ولوزير المالية أو من يفوضه الخصم من خلال البنك المركزى المصري مستحقات الدولة في أرباح الشركات القابضة طبقا لحساب التوزيع المصادق عليه من الجمعية العامة على حسابات هذه الشركات بالجهاز المصرفي و ذلك في حالة تخلفها عن السداد في موعد غايتها ستة أشهر من قرار الجمعية العامة بتوزيع الأرباح.
(*) الفقرة الأخيرة من المادة 14 أضيفت بالقانون رقم 149 لسنة 2001 الصادر بالجريدة الرسمية –العدد رقم 25 مكرر (أ) الصادر في 2001/6/24$m228$,'fdea98835cfb20fce64262abdf1e4820'),
(15,0,$m228$المادة 15$m228$,$m228$يتولى الجهاز المركزى للمحاسبات مراقبة حسابات الشركة وتقييم أدائها طبقا لقانونه.
ويجوز للجمعية العامة للشركة تعيين مرقب حسابات أخر للشركة، بالإضافة إلى مراقب الجهاز المركزي للمحاسبات من مراقبي الحسابات المقيدين بسجلات الهيئة العامة الرقابة المالية، على أن تحدد الجمعية العامة أتعابه.
*الفقرة الثانية مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'eaf20b74930c47010c1be3970c05a485'),
(16,0,$m228$المادة 16$m228$,$m228$مع عدم الإخلال بحكم المادة (39 مكرر) من هذا القانون، تعتبر شركة تابعة في تطبيق أحكام هذا القانون الشركة التي يكون لأحدى الشركات القابضة أكثر من (50%) من رأسمالها أو من حقوق التصويت بها.
فإذا اشترك في هذه النسبة أكثر من شركة من الشركات القابضة أو الأشخاص الاعتبارية العامة أو بنوك القطاع العام يصدر رئيس مجلس الوزراء قرارا بتحديد الشركة القابضة التى تتبعها هذه الشركة.
و تتخذ الشركة التابعة شكل شركة المساهمة و تثبت لها الشخصية الاعتبارية من تاريخ قيدها في السجل التجاري.
*الفقرة الأولى معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'839ed6f9c4c6a7f819819a3ee2585f58'),
(17,0,$m228$المادة 17$m228$,$m228$يصدر بتأسيس الشركة التابعة قرار من الوزير المختص بناء على اقتراح مجلس إدارة الشركة القابضة و ينشر هذا القرار مرفقا به النظام الأساسي على نفقة الشركة في الوقائع المصرية و تقيد الشركة في السجل التجارى.$m228$,'1555e1e2189786176b208ec2d329bf36'),
(18,0,$m228$المادة 18$m228$,$m228$يقسم رأسمال الشركة إلى أسهم اسمية متساوية القيمة.
ويحدد النظام الأساسي القيمة الاسمية للسهم بما لا يقل عن الحد الأدنى وفق لقانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 ويكون للسهم غير قابل للتجزئة، ولا يجوز إصداره بأقل من قيمته الأسمية، كما لا يجوز إصداره بقيمة أعلى إلا في الأحوال وبالشروط المبينة في قانون سوق رأس المال المشار إليه ولائحته التنفيذية، على أن تضاف هذه الزيادة إلى الاحتياطي.
ولا يجوز بأي حال أن تجاوز مصاريف الإصدار الحد الذي يصدر به قرار من الهيئة العامة للرقابة المالية.
ويتم إيداع أسهم الشركة لدى إحدى الشركات أو الجهات المرخص لها بنشاط الإيداع والقيد المركزي للأوراق والأدوات المالية.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'a841748e3c940124acdcf1e9a01dc2ac'),
(19,0,$m228$المادة 19$m228$,$m228$تشكل بقرار من الوزير المختص لجنة أو أكثر برئاسة أحد أعضاء الجهات أو الهيئات القضائية بدرجة مستشار على الأقل تختاره جهة عمله، وعضوية ممثل عن كل من وزارة المالية، والجهاز المركزي للمحاسبات، وممثل عن المؤسسين أو المساهمين يختاره مجلس إدارة الشركة القابضة أو التابعة بحسب الأحوال، وأربعة على الأكثر من ذوي الخبرة الاقتصادية والمحاسبية والقانونية والفنية يختارهم الوزير المختص.
وتتولى اللجنة المشار إليها بالفقرة السابقة التحقق من صحة تقييم الأصول الأتية:
1 - الحصص العينية المالية والمعنوية الداخلة في رأسمال الشركات الخاضعة لأحكام هذا القانون عند التأسيس أو الاندماج أو عند زيادة رأس المال.
2 - الأسهم والحصص التي تملكها الدولة في الشركات القابضة.
3 - الأسهم والحصص التي تمتلكها الشركة القابضة في شركاتها التابعة او تمتلكها في غيرها من الشركات الأخرى قبل التصرف فيها.
4 - أسهم الشركات الخاضعة لأحكام هذا القانون في حالات مبادلتها بأسهم في شركات أخرى.
5 - الأصول العقارية غير المستغلة التي تقرر الشركة التصرف فيها.
وعلى اللجنة تقديم تقريرها إلى الوزير المختص أو الشركة بحسب الأحوال في مدة أقصاها ثلاثون يوما من تاريخ إحالة الأوراق إليها، وتحدد اللائحة التنفيذية لهذا القانون القواعد والإجراءات الواجب الالتزام بها عند القيام بأعمال التقييم واعتماده بمراعاة معايير التقييم المالي للمنشآت والمعايير المصرية للتقييم العقاري.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'b57b075fee25d380683a151a66ebbe7c'),
(20,0,$m228$المادة 20$m228$,$m228$تكون أسهم الشركة قابلة للتداول فور إصدارها، ويكون تداول او نقل ملكية أسهم الشركات الخاضعة لهذا القانون بمراعاة أحكام هذا القانون ولائحته التنفيذية والقواعد المطبقة بالبورصات المصرية.
و يجوز تداول حصص التأسيس و الأسهم التى تعطى مقابل حصة عينية و الأسهم التى يكتتب فيها مؤسسو الشركة من تاريخ قيدها في السجل التجارى.
*الفقرة الأولى معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'0d73dc1329fd1f1f0f8454307376d974'),
(21,0,$m228$المادة 21$m228$,$m228$مع مراعاة حكم المادة (4) من هذا القانون، يتولى إدارة الشركة التابعة مجلس إدارة تختاره الجمعية العامة لمدة ثلاث سنوات قابلة للتجديد.
ويجتمع مجلس الإدارة مرة على الأقل كل شهر بدعوة من رئيسه، وفي حالة غيابه يندب رئيس الجمعية العامة من بين أعضاء المجلس من يرأس الاجتماع.
ويتكون مجلس الإدارة من عدد من الأعضاء يحدده النظام الأساسي لا يقل عن خمسة ولا يزيد على تسعة بمن فيهم رئيس المجلس على النحو الآتي:
(أ) رئيس غير تنفيذي، تختاره للجمعية العامة للشركة بناء على ترشيح مجلس إدارة الشركة القابضة.
(ب) أعضاء يمثلون المساهمين بالشركة وفقا لهيكل ملكية الشركة بمراعاة قواعد التمثيل النسبي، تعينهم الجمعية العامة مع عدم الإخلال بحق الشخص الاعتباري المساهم في الشركة في تغيير ممثليه خلال مدة المجلس.
(ج) ممثل لو اثنان من العاملين بالشركة بحسب عدد أعضاء مجلس الإدارة، يتم انتخابه أو انتخابهما طبقا لأحكام للقانون المنظم لذلك.
ويجوز أن يتضمن النظام الأساسي للشركة أعضاء مستقلين إضافيين من ذوي الخبرة بمجلس الإدارة لا يزيد عددهم على عضوين تختارهما الجمعية العامة بناء على ترشيح مجلس إدارة الشركة القابضة.
وتحدد الجمعية العامة سنويا ما يتقاضاه كل من رئيس وأعضاء المجلس المشار إليهم من بدلات الحضور والانتقال للجلسات و المكافأة السنوية التي يستحقها مجلس الإدارة بمراعاة نص المادة (34) من هذا القانون، كما تحدد الجمعية العامة المزايا الأخرى للأعضاء المنتدبين بما في ذلك التأمين الطبي ووسائل الانتقال.
وفي جميع الأحوال، لا يجوز أن يزيد بدل الحضور والانتقال لرئيس وأعضاء المجلس عن الحد الذي يصدر به قرار من رئيس مجلس الوزراء.
ويختار مجلس إدارة الشركة من بين أعضاء المجلس العضو المكتب التنفيذي وغيره من الأعضاء المنتدبين للإدارة ويحدد ما يتقاضونه من راتب بالإضافة إلى ما يستحقونه من مبالغ طبقا للفقرة الخامسة من هذه المادة.
ويحدد المجلس من يحل محل العضو المنتدب في حالة غيابه لو خلو منصبه أو تغييره.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'12c91bf66f79e4ec9fa5ca1c9854e472'),
(22,0,$m228$المادة 22$m228$,$m228$ملغاة.
*ألغيت بموجب قانون رقم 185 لسنة 2020.$m228$,'a2cdac74325ab055ba23c3330b2c314d'),
(23,0,$m228$المادة 23$m228$,$m228$لعضو مجلس الإدارةالمنتدب جميع السلطات المتعلقة بإدارة الشركةو القيام بكافة الأعمال اللازمة لتحقيق غرضها و ذلك فيماعدا ما يدخل في إختصاص الجمعية العامة و مجلس الإدارة طبقا لأحكام هذا القانون و لائحته التنفيذية و نظام الشركة.$m228$,'9a72d4d82386cd3c70c6089cbc71c040'),
(24,0,$m228$المادة 24$m228$,$m228$يمثل عضو مجلس الإدارة المنتدب الشركة أمام القضاء و في صالتها بالغير.$m228$,'70da2e1de2b65db1cdbe0b6af41e07e6'),
(25,0,$m228$المادة 25$m228$,$m228$تتكون الجمعية العامة للشركة على النحو الآتي:
1 - رئيس مجلس إدارة الشركة القابضة أو من يحل محله في حالة غيابه، رئيس.
2 - ممثلون للشركة القابضة والأشخاص الاعتبارية العامة المساهمة في الشركة تختارهم السلطة المختصة بكل منها.
3 - المساهمون من الأشخاص الاعتبارية الخاصة أو الأفراد في رأسمال الشركة.
4 - عضو تختاره اللجنة النقابية للشركة.
ويجوز أن يضم لتشكيل الجمعية العامة بالشركات التابعة التي تمتلكها الشركات القابضة بمفردها أو مع غيرها من الأشخاص الاعتبارية العامة أو بنوك القطاع العام أربعة أعضاء على الأكثر من ذوي الخبرة تختارهم الجمعية العامة للشركة القابضة، وتحدد ما يتقاضونه من بدل الحضور والانتقال.
ويحضر اجتماعات الجمعية العامة رئيس وأعضاء مجلس إدارة الشركة، ومراقبو الحسابات من الجهاز المركزي للمحاسبات، ومراقب الحسابات المعين من الجمعية العامة للشركة إن وجد، دون أن يكون لهم صوت معدود.
ويكون لكل مساهم التصويت في الجمعية العامة بنسبة ما يمتلكه من أسهم في رأسمال الشركة أو حقوق تصويت فيها، وتصدر قرارات الجمعية العامة بأغلبية الأسهم الحاضرة بالاجتماع فيما عدا الأحوال التي تتطلب فيها اللائحة التنفيذية أو النظام الأساسي للشركة أغلبية خاصة.
وتبين اللائحة التنفيذية لهذا القانون شروط صحة انعقاد الجمعية العامة ونظام التصويت على المسائل المعروضة عليها بحسب ما إذا كانت الجمعية العامة منعقدة في اجتماع عادي أو غير عادي.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'89a505ded944b4a1995717861d5d2d08'),
(26,0,$m228$المادة 26$m228$,$m228$ملغاة.
*ألغيت بموجب قانون رقم 185 لسنة 2020.$m228$,'a2cdac74325ab055ba23c3330b2c314d'),
(27,0,$m228$المادة 27$m228$,$m228$مع مراعاة أحكام هذا القانون ولائحته التنفيذية و النظام الأساسي تختص الجمعية العامة العادية بما يأتى:
(أ) التصديق على الميزانية و حساب الأرباح و الخسائر.
(ب) التصديق على تقرير مجلس الإدارة عن نشاط الشركة و النظر في إخلائه من المسئولية.
(ج) الموافقة على توزيع الأرباح.
(د) الموافقة على استمرار رئيس و اعضاء مجلس الإدارة لمدة تاليه أو عزلهم و يكون التصويت على ذلك بطريق الإقتراع السري.
(ه) كل ما يري رئيس الجمعية العامة للشركة أو رئيس مجلس إدارة الشركة القابضة أو مجلس إدارة الشركة التابعة لهاأ و المساهمون من الأشخاص الإعتبارية من القطاع الخاص أو الأفراد الذين يملكون 10% من رأس المال عرضه على الجمعية العامة.$m228$,'1876afb4c2d0de0b5ac4775bb714adab'),
(28,0,$m228$المادة 28$m228$,$m228$لا يجوز تعديل النظام الأساسي إلا بموافقة الجمعية العامة غير العادية ووفقا لأحكام اللائحة التنفيذية.$m228$,'027896bc62764988ef8f981745d112f1'),
(29,0,$m228$المادة 29$m228$,$m228$ملغاة.
*ألغيت بموجب قانون رقم 185 لسنة 2020.$m228$,'a2cdac74325ab055ba23c3330b2c314d'),
(30,0,$m228$المادة 30$m228$,$m228$مع عدم الإخلال بأحكام هذا القانون تسري على الجمعيات العامة للشركات التى يساهم فيها مع الشركة القابضة أشخاص إعتبارية من القطاع الخاص أو الأفراد أحكام المواد من 59 إلي 76 من القانون رقم 159 لسنة 1981 المشار إليه.$m228$,'0d876a3212c363f6383b7910b64956ba'),
(30,1,$m228$المادة 30 مكرراً$m228$,$m228$لرئيس مجلس الوزراء بعد موافقة مجلس الوزراء نقل ملكية أسهم أي من الشركات التابعة المملوكة أسهمها بالكامل لإحدى الشركات القابضة الخاضعة لأحكام هذا القانون إلى أي من الأشخاص الاعتبارية العامة أو صندوق مصر السيادي للاستثمار والتنمية، على أن تخضع للشركات المنقولة ملكيتها لأحكام قانون شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة وشركات الشخص الواحد الصادر بالقانون رقم 159 لسنة 1981
*مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'1de0b10b1cf9489021f42ad933adc5c0'),
(31,0,$m228$المادة 31$m228$,$m228$يحدد النظام الأساسي بداية و نهاية السنة المالية للشركة بمراعاة السنة المالية للشركة القابضة التى تتبعها.$m228$,'0610a36555a924ef634ff4b4e3962398'),
(32,0,$m228$المادة 32$m228$,$m228$الأرباح الصافية هى الأرباح الناتجة عن العمليات التى باشرتها الشركة و ذلك بعد خصم جميع التكاليف اللازمة لتحقيق هذه الأرباح و بعد حساب و تجنيب كافة الإهلاكات و المخصصات التى تقضي الأصول المحاسبية بحسابها و تجنيبها قبل إجراء أي توزيع بأية صور من الصور للأرباح.
و يجنب مجلس الإدارة من صافي الأرباح المشار إليها في الفقرة السابقة جزءا من عشرين على الأقل لتكويسن احتياطى قانونى و يجوز للجمعية العامة للشسركة وقف تجنيب هذا الإحتياطى أو تخفيض نسبته إذا بلغ ما يساوى نصف رأس المال.
و يجوز استخدام الإحتياطى القانونى في تغطية خسائر الشركة و في زيادة رأس المال.
كما يجوز أن ينص في نظام الشركة على تجنيب نسبة معينة من الأرباح الصافية لتكوين احتياطيات أخرى، بشرط تحديد أسباب تكوينها -ويتم اعتمادها من الجمعية العامة.
و تبين اللائحة التنفيذية قواعد وأحكام توزيع الأرباح القابلة للتوزيع.
*الفقرة الرابعة معدلة بموجب قانون رقم 185 لسنة 2020.
*الفقرتان الخامسة والسادسة ألغيت بموجب قانون رقم 185 لسنة 2020.$m228$,'c4236de2e085412c73637740998df147'),
(33,0,$m228$المادة 33$m228$,$m228$يكون للعاملين بالشركة نصيب في الأرباح السنوية القابلة للتوزيع، يصدر به قرار من الجمعية العامة بناء على عرض مجلس الإدارة بنسبة لا تقل عن (10%) ولا تزيد على (12%) من هذه الأرباح تصرف نقدا، بمراعاة أحكام قانون تنظيم استخدام وسائل الدفع غير النقدي الصادر بالقانون رقم 18 لسنة 2019.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'7a37c01fc899edda5861e4b268bc83d0'),
(34,0,$m228$المادة 34$m228$,$m228$يبين للنظام الأساسي للشركة كيفية تحديد وتوزيع مكافأة أعضاء مجلس الإدارة، ولا يجوز تقدير مكافأة مجلس الإدارة بأكثر من (5%) بالنسبة للشركات القابضة و(10%) بالنسبة للشركات التابعة وذلك من أرباح الشركة السنوية القابلة للتوزيع مخصوصا منها نسبة (5%) من رأس المال المدفوع.
ويكون للجمعية العامة تقرير ما تراه مناسبا في شأن توزيع باقي أرباح الشركة بعد خصم حصة العاملين ومجلس الإدارة على المساهمين من عدمه وذلك في ضوء التزامات الشركة ومشروعاتها.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'8f1dc47af5dbc27cc3878a1010ad6889'),
(35,0,$m228$المادة 35$m228$,$m228$يتولى الجهاز المركزى للمحاسبات مراقبة حسابات الشركة وتقييم أدائها طبقا لقانونه.
ويجوز للجمعية العامة للشركة تعيين مراقب حسابات آخر للشركة، بالإضافة إلي مراقب الجهاز المركزي للمحاسبات من مراقبي الحسابات المقيدين بسجلات الهيئة العامة للرقابة المالية، على أن تحدد الجمعية العامة أتعابه.
*الفقرة الثانية مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'88a1b2f7830bf59d81637a2c0adac6c5'),
(35,1,$m228$المادة 35 مكرراً$m228$,$m228$تلتزم الشركات الخاضعة لأحكام هذا القانون وغير المقيدة بالبورصات المصرية بالآتي:
1 - نشر تقارير دورية نصف سنوية عن أدائها ونتائج أعمالها، متضمنة أداء ونتائج أعمال الشركات التي تساهم فيها، وأي أحداث جوهرية مرتبطة بهذه الشركة والشركات التي تساهم فيها ومجالس إداراتها خلال هذه الفترة.
2 - نشر تقرير مجلس الإدارة السنوي المعروض على الجمعية العامة، وكذا القوائم المالية السنوية والإيضاحات المتممة لها، وتقرير مراقبي الحسابات في شأنها.
3 - نشر القرارات الصادرة عن الجمعية العامة العادية وغير العادية للشركة.
4 - البيانات والمعلومات الأخرى التي تحددها اللائحة التنفيذية لهذا القانون.
وتحدد اللائحة التنفيذية لهذا القانون رسائل ومواعيد النشر والقواعد الواجب اتباعها في شأن إعداد هذه التقارير.
*مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'4d6e37f8ee97c1f227671c0f23e6d1b3'),
(35,2,$m228$المادة 35 مكرراً (1)$m228$,$m228$تلتزم الشركات الخاضعة لأحكام هذا القانون بقواعد الحوكمة والإدارة الرشيدة التي يصدر بتحديدها قرار من رئيس مجلس الوزراء.
وعلى مجلس إدارة الشركة إعداد تقرير سنوي عن مدى تطبيق قواعد الحوكمة والإدارة الرشيدة بها وخطتها للامتثال لباقي متطلباتها، وذلك للعرض على الجمعية العامة.
*مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'88871dd48e958b0fda648148ce2c7b52'),
(36,0,$m228$المادة 36$m228$,$m228$يجوز بقرار من رئيس مجلس الوزراء تقسيم و إدماج الشركات القابضة بناء على عرض الوزير المختص.
كما يجوز تقسيم و إدماج الشركات التابعة لها وذلك بقرار من مجلس إدارة الشركة أو الشركات القابضة وإعتماد الجمعيات العامة للشركات المندمجة و المندمج فيها حسب الأحوال.
و يكون لكل شركة نشأت عن الإندماج أو التقسيم الشخصية الإعتبارية المستقلة مع ما يترتب على ذلك من آثار قانونية.
و مع مراعاة أحكام هذا القانون و لائحته التنفيذية تسري على حالات الإندماج أحكام المواد 130 إلي 135 من القانون رقم 159 لسنة 1981 المشار إليه.$m228$,'b7e640480186e774b32f40a89338f584'),
(37,0,$m228$المادة 37$m228$,$m228$تتولى تقدير صافي أصول الشركات في حالات الإندماج والتقسيم اللجنة المنصوص عليها في المادة (19) من هذا القانون و يجب أن تعتمد قرارت اللجنة بالنسبة للشركات القابضة من الوزير المختص و بالنسبة للشركات التابعة من الجمعية العامة للشركة المندمجة والشركة المندمج فيها أو الشركة المقسمة بحسب الأحوال.$m228$,'1888ce20d233b1557b3f0eaac63671dd'),
(38,0,$m228$المادة 38$m228$,$m228$إذا بلغت خسائر الشركة نصف رأس المال المصدر وجب على مجلس الإدارة أن يبادر إلي دعوة الجمعية العامة غير العادية للنظر في حل الشركة و استمرارها.
وفي جميع الأحوال إذا بلغت قيمة خسائر الشركة كامل حقوق المساهمين بالشركة يتم عرض الأمر على الجمعية العامة للشركة لزيادة رأسمالها لتغطية الخسائر المرحلة، وفي حال عدم زيادة رأسمال الشركة وفقا لما سبق وجب العرض علي الجمعية العامة غير العادية لحل وتصفية الشركة أو دمجها في شركة أخرى مع الحفاظ على حقوق العاملين بها بما لا يقل عما تضمنه قانون العمل المشار إليه، ودون الإخلال بأحكام القانون رقم 125 لسنة 2010 بشان مرتبة امتياز حقوق العمال، وذلك كله وفقا للقواعد التي تحددها اللائحة التنفيذية لهذا القانون.
*الفقرة الثانية مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'9af114f7a6c6a9baad42423efe20f714'),
(39,0,$m228$المادة 39$m228$,$m228$تنقضى الشركة بأحد الأسباب الآتية:
1 - حل الشركة.
2 - انتهاء المدة المحدة في نظام الشركة.
3 - انتهاء الغرض الذي أسست الشركة من أجله.
4 - الإندماج و التقسيم.
وتكون الشركة المنقضية في حالة تصفية و تطبق عليها أحكام المواد من 137 إلي 154 من القانون رقم 159 لسنة 1981 المشار إليه و لائحته التنفيذية.$m228$,'ebd4d44ef6c02dbac0a1dc0fddda0a38'),
(39,1,$m228$المادة 39 مكرراً$m228$,$m228$في الأحوال التي يترتب فيها على طرح أسهم الشركة التابعة بإحدى البورصات المصرية وصول نسبة المساهمين بخلاف الدولة والشركات القابضة الخاضعة لهذا القانون و الأشخاص الاعتبارية العامة وبنوك القطاع العام في ملكية الشركة التابعة إلى (25%) أو أكثر في رأسمال الشركة، يتم نقل تبعية الشركة لأحكام للقانون رقم 159 لسنة 1981 وفقا للإجراءات وخلال المدة التي تحددها اللائحة التنفيذية لهذا القانون.
*مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'a09b108d6c89fdc93251eb5434f1ecba'),
(40,0,$m228$المادة 40$m228$,$m228$يجوز الإتفاق على التحكيم في المنازعات التى تقع فيما بين الشركات الخاضعة لأحكام هذا القانون أو بينها و بين الأشخاص الإعتبارية العامة أو الأشخاص الإعتبارية من القطاع الخاص أو الأفراد وطنيين كانوا أو أجانب و تطبق في هذا الشأن أحكام الباب الثالث من الكتاب الثالث من قانون المرافعات المدنية والتجارية.$m228$,'a578599982284647b634afa80b8d0582'),
(41,0,$m228$المادة 41$m228$,$m228$طلبات التحكيم بين شركات القطاع العام أو بينها و بين جهة حكومية مركزية أو محلية أو هيئة قطاع عام أو مؤسسة عامة التى قدمت قبل تاريخ العمل بهذا القانون و كذلك منازعات التنفيذ الوقتية في الأحكام الصادرة فيها يستمر نظرها أما م هيئات التحكيم المشكلة طبقا لأحكام قانون هيئات القطاع العام و شركاته الصادر بالقانون رقم 97 لسنة 1983 و طبقا للأحكام و الإجرءات المنصوص عليها فيه.$m228$,'87233ac170515d23d9633ba5b02bd0aa'),
(42,0,$m228$المادة 42$m228$,$m228$يضع مجلس إدارة الشركة بعد أخذ رأي النقابة العامة المختصة اللوائح المتعلقة بنظام العاملين بها.
وتتضمن هذه اللوائح على الأخص نظام الأجور والعلاوات والبدلات والإجازات طبقا للتنظيم الخاص بكل شركة، وتعتمد هذه اللوائح أو أي تعديل بها من الجمعية العامة للشركة، ويصدر بها قرار من الوزير المختص.
كما يضع مجلس إدارة الشركة لائحة العمل بالإدارة القانونية بها، متضمنة على الأخص نظام عملها وتحديد اختصاصات أعضائها وتأديبهم، بما يكفل لهم الحيدة والاستقلالية في مباشرة اعملاهم، وتعتمد هذه اللائحة وأي تعديل لها بقرار من الوزير المختص.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'1d20e893c7e250440e6ef8a3929d52cc'),
(43,0,$m228$المادة 43$m228$,$m228$يراعى في وضع اللوائح المنظمة لشئون العاملين ما يأتى:
أولا - أن يكون لكل شركة هيكل تنظيمى و جدول للوظائف بما يتفق مع طبيعة أنشطة الشركة و أهدافها.
ثانيا - التزام نظام الأجور بالحد الأدنى المقرر قانونا.
ثالثا - ربط الأجر و نظام الحوافز و البدلات و المكافآت و سائر التعويضات و المزايا المالية للعاملين في ضوء ما تحققه الشركة من إنتاج أو رقم أعمال وما تحققه من أرباح.$m228$,'a353e4deb5e91bc32a5b9d9f6eae4b2b'),
(44,0,$m228$المادة 44$m228$,$m228$ملغاة.
*ألغيت بموجب قانون رقم 185 لسنة 2020.$m228$,'a2cdac74325ab055ba23c3330b2c314d'),
(45,0,$m228$المادة 45$m228$,$m228$تنتهى خدمة العامل لأحد الأسباب الآتية:
1 - فقد الجنسية المصرية أو إنتفاتء شرط المعاملة بالمثل بالنسبة لرعايا الدول الأخرى.
2 - بلوغ سن الستين و ذلك بمراعاة أحكام قانون التأمين الاجتماعي الصادر بالقانون رقم 79 لسنة 1975.
3 - عدم اللياقة للخدمة الصحية.
4 - صدور حكم بات بعقوبة جناية أو بعقوبة مقيدة للحرية في جريمة مخلة بالشرف أو الأمانة ما لم يكن الحكم مع وقف التنفيذ الشامل.
و دون إخلال بأحكام قانون العقوبات إذا كان قد حكم عليه لأول مرة فلا يؤدي ذلك إلي انتهاء الخدمة إلا إذا قدرت لجنة شئون العاملين بقرار مسبب من واقع أسباب الحكم و ظروف الواقعة أن بقاءه في الخدمة يتعارض مع مقتضيات الوظيفة أو طبيعة العمل.
5 - انتهاء العمل العرضي أو المؤقت أو الموسمى.
6 - الاستقالة.
7 - الاحالة الى المعاش أو الفصل.
8 - الوفاة.
وتحدد اللائحة التنفيذية الأوضاع والإجراءات الخاصة بانتهاء خدمة العامل بسبب الاستقالة أو عدم اللياقة للخدمة صحيا.$m228$,'3c90493ec58d6816f6f355518ca7d5a4'),
(46,0,$m228$المادة 46$m228$,$m228$يجوز عند الضرورة القصوى بقرار من رئيس مجلس الوزراء مد خدمة أي من العاملين من شاغلي الوظائف القيادية أصحاب الخبرة الفنية النادرة بالشركة لمدة سنة قابلة للتجديد لمدة أقصاها سنتان.
وأما بالنسبة للعاملين بالشركات من غير شاغلي الوظائف القيادية فلا يجوز مد خدمة أي منهم بعد بلوغ سن التقاعد أو تكليفه أو التعاقد معه بأي مسمي أو صفة في أي من الشركات الخاضعة لأحكام هذا القانون إلا بموافقة الوزير المختص عند الضرورة وبما لا يجاوز عامين.
*الفقرة الثانية مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'bd1a9603420d7aebe6250382001e9f86'),
(47,0,$m228$المادة 47$m228$,$m228$يكون نقل رؤساء وحدات الأمن في الشركات الخاضعة لأحكام هذا القانون و العاملين بهذه الوحدات بقرار من السلطة المختصة في الشركة دون حاجة لأي إجراء آخر.$m228$,'aa1d5259220b92cdbda0cd6c3816f72e'),
(48,0,$m228$المادة 48$m228$,$m228$تسرى في شأن واجبات العاملين بالشركات القابضة والتابعة والتحقيق معهم وتأديبهم أحكام قانون العمل الصادر بالقانون رقم 12 لسنة 2003 كما تسري أحكام قانون العمل المشار إليه، بما في ذلك الأحكام المنظمة للمفاوضة الجماعية على العاملين بالشركات القابضة والتابعة، فيما لم يرد في شأنه نص خاص في هذا القانون أو اللوائح الصادرة تنفيذا له.
ويجوز للوزير المختص أو مجلس إدارة الشركة أن يطلب من النيابة الإدارية التحقيق مع أي من العاملين بهذه الشركات في الحالات التي يقدرونها، ويتم موافاة الوزير المختص أو مجلس إدارة الشركة بنتيجة هذا التحقيق لتتولى السلطة المختصة بالشركة اتخاذ الإجراء أو القرار التأديبي المناسب.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'1b56e838d90007c56e9e66b541df8fc2'),
(49,0,$m228$المادة 49$m228$,$m228$مع عدم الإخلال بأية عقوبة أو وصف قانونى أشد ينص عليها قانون العقوبات أو أي قانون آخر يعاقب بالحبس مدة لا تقل عن سنتين و بغرامة لا تقل عن ألفى جنيه و لا تجاوز عشرة آلاف جنيه أو بأحدي هاتين العقوبتين كل من ارتكب أحد الأفعال الآتية:
1 - كل من عبث عمدا في نظام الشركات أو في نشرات الإكتتاب أو في غير ذلك من وثائق الشركة أو أثبت بها بيانات غير صحيحة أو مخالفة لأحكام هذا القانون أو قانون شركة المساهمة المشار إليها و كل من وقع هذه الوثائق أو وزعها مع علمه بذلك.
2 - كل من قوم بسوء قصد الحصص العينية المقدمة من الشركاء بأكثر من قيمتها الحقيقية.
3 - كل مديرأو عضو مجلس إدارة وزع على المساهمين أو غيرهم أرباحا أو فوائد على خلاف أحكام هذا القانون أو نظام الشركة و كل مراقب حسابات أقر هذا التوزيع.
4 - كل مدير أو عضو مجلس إدارة أو مصف ذكر عمدا بيانات غير صحيحة في الميزانية أو في حساب الأرباح و الخسائر أو أغفل عمدا ذكر و قائع جوهرية في هذه الوثائق.
5 - كل مراقب حسابات تعمد وضع تقرير غير صحيح عن نتيجة مراجعته أو أخفي عمدا وقائع جوهرية في هذا التقرير.
6 - كل مدير أو عضو مجلس إدارة او مراقب حسابات أو معاون له او عامل لديه و كل شخص يعهد إليه بالتفتيش على الشركة أفشى ما يحصل عليه بحكم عمله من أسرار الشركة أو أستغل هذه الأسرار لجلب نفع خاص له ولغيره.
7 - كل شخص عين من قبل الجهة الإدارية المختصة للتفتيش على الشركة أثبت عمدا في تقريره عن نتيجة التفتيش و قائع كاذبة أو اغفل عمدا في تقريره وقائع جوهرية من شأنها ان تؤثر في نتيجة التفتيش.$m228$,'3108a3bca773755a3c0d2f838f5976ab'),
(50,0,$m228$المادة 50$m228$,$m228$مع عدم الإخلال بأية عقوبة أشد ينص عليها قانون العقوبات أو اى قانون أخر يعاقب بغرامة لا تقل عن خمسمائة جنيه ولا تجاوز خمسة ألاف جنيه كل من يصدر أسهما أو صكوكا أو سندات أو إيصالات اكتتاب أو شهادات مؤقتة أو يعرضها للتداول على خلاف الأحكام المقررة فى هذا القانون.$m228$,'494c9cdcf68f0f8ee03b278c8696cf92'),
(51,0,$m228$المادة 51$m228$,$m228$تضاعف في حالة العود الغرامات المنصوص عليها في المادتين السابقتين في حديها الأدنى و الأقصي.$m228$,'4a9d48f25d085fa3121b71d921115224'),
(52,0,$m228$المادة 52$m228$,$m228$تعتبر أموال الشركات الخاضعة لأحكام هذا القانون في حكم الأموال العامة كما يعد القائمون على إدارتها و العاملون فيها في حكم الموظفين العموميين و ذلك في تطبيق أحكام البابين الثالث و الرابع من الكتاب الثانى من قانون العقوبات.$m228$,'7aefb4f8ef88e22c2904f560d04351e6'),
(53,0,$m228$المادة 53$m228$,$m228$لا يجوز إحالة الدعوى الجنائية إلي المحكمة في الجرائم المشار إليها في المواد 116 مكررا و(116 أ) و 116 مكرر(ب) من قانون العقوبات بالنسبة إلي أعضاء مجالس إدارة الشركات الخاضعة لحكام هذا القانون إلا بناء على أمر من النائب العام أو من النائب المساعد أو من المحامى العام الأول.$m228$,'e08217d12b551bd6c4486d86d09963c5'),
(54,0,$m228$المادة 54$m228$,$m228$يكون للمكلفين بإثبات الجرائم التى تقع بالمخالفة لأحكام هذا القانون و القرارات الصادرة تنفيذا له الذين يصدر بتحديدهم قرار من وزير العدل بالإتفاق مع الوزير المختص حق الإطلاع على جميع سجلات ودفاتر الشركة القابضة أو الشركات التابعة لها.
و على رئيس وأعضاء مجلس الإدارة و العضو المنتدب و مراقب الحسابات و سائر العاملين بهذه الشركات أن يقدموا إليهم جميع البيانات و المعلومات والمستندات و الوثائق و السجلات والدفاتر التى يطلبونها لأداء عملهم.$m228$,'797546566a9447f742cd55d1c6dcd011'),
(55,0,$m228$المادة 55$m228$,$m228$مع عدم الإخلال بحكم المادة (54) من هذا القانون أو بأي حكم وارد في أي قانون آخر، لا يجوز لأي جهة رقابية بالدولة عدا الجهاز المركزي للمحاسبات وهيئة الرقابة الإدارية أن تباشر أي عمل من أعمال الرقابة داخل المقر الرئيسي أو المقار الفرعية لأي شركة من الشركات الخاضعة لأحكام هذا القانون إلا بعد الحصول على إذن بذلك من الوزير المختص أو رئيس مجلس إدارة الشركة القابضة.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'43a5f0f041f04e14638d746bd6c676ae');

INSERT INTO m228_ver VALUES
(0,0,1,$m228$قانون رقم 203 لسنة 1991 بتاريخ 19/06/1991 بشأن اصدار قانون شركات قطاع الاعمال العام$m228$,'cf2820cad4cf13bbab3f5cfb51b20149',DATE '1991-06-19',NULL,'active',NULL,NULL,NULL),
(1,-1,1,$m228$يعمل في شأن قطاع الأعمال العام بأحكام القانون المرافق، و يقصد بهذا القطاع الشركات القابضة و الشركات التابعة لها الخاضعة لأحكام هذا القانون، وتتخذ هذه الشركات بنوعيها شكل شركات المساهمة و يسرى عليها فيما لم يرد بشأنه نص خاص في هذا القانون و لا يتعارض مع أحكامه نصوص قانون شركات المساهمة و شركات التوصية بالأسهم و الشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981.
و لا تسرى أحكام قانون هيئات القطاع العام و شركاته الصادر بالقانون رقم 97 لسنة 1983 على الشركات المشار إليها.$m228$,'4ec9f5a5b2472202c97a96542b37b720',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(1,0,1,$m228$يصدر بتأسيس الشركة القابضة قرار من رئيس مجلس الوزراء بناء على اقتراح الوزير المختص و يكون رأسمالها مملوكا بالكامل للدولة أو للأشخاص الاعتبارية العامة و تثبت لها الشخصية الاعتبارية من تاريخ قيدها في السجل التجاري.
و تأخذ الشركة القابضة شكل شركة المساهمة و تعتبر من أشخاص القانون الخاص و يحددالقرار الصادر بتأسيسها اسمها و مركزها الرئيسى و مدتها و الغرض الذي أنشئت من أجله و رأس مالها.
و ينشر القرار الصادر بتأسيس الشركة مع نظامها الأساسي على نفقتها في الوقائع المصرية و تقيد الشركة في السجل التجارى.$m228$,'cfb586ace0a30f682d2b79b5b5c59264',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(2,-1,1,$m228$تحل الشركات القابضة محل هيئات القطاع العام الخاضعة لأحكام القانون رقم 97 لسنة 1983 المشار إليه كما تحل الشركات التابعة محل الشركات التى تشرف عليها هذه الهيئات وذلك اعتبارا من تاريخ العمل بهذا القانون ودون حاجة الى أى اجراء أخر.
و تنتقل إلي الشركات القابضة و الشركات التابعة لها بحسب الأحوال كافة ما لهيئات القطاع العام القطاع العام و شركاته الملغاة من حقوق بما فيها حقوق الانتفاع والإيجار كما تتحمل جميع التزاماتها وتسأل مسئولية كاملة عنها.
و ينشر النظام الأساسي لكل شركة من الشركات القابضة والتابعة على نفقتها في الوقائع المصرية و تقيد في السجل التجارى.$m228$,'33c87ea180f1a8b2f74f337c19a53620',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(2,0,1,$m228$تتولى الشركة القابضة من خلال الشركات التابعة لها إستثمار أموالها كما يكون لها عند الاقتضاء أن تقوم بالإستثمار بنفسها.
و تتولى الشركة القابضة في مجال نشاطها و من خلال الشركات التابعة لها المشاركة في تنمية الاقتصاد القومى في إطار السياسية العامة للدولة.
وللشركة أيضا في سبيل تحقيق أغراضها القيام بالأعمال الآتية:
1 - تأسيس شركات مساهمة بمفردها أو بأالشتراك مع الأشخاص الاعتبارية العامة أو الخاصة أو الأفرد
2 - شراء أسهم شركات المساهمة أو بيعها أو المساهمة في رأسمالها.
3 - تكوين وإدارة محفظة الأوراق المالية للشركة بما تتضمنه من أسهم و صكوك تمويل و سندات و أية أدوات أو أصول مالية أخرى.
4 - إجراء جميع التصرفات التى من شأنها أن تساعد في تحقيق كل أو بعض أغراضها.$m228$,'9be2261993f967010c35a3f48bea8dbd',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(3,-1,1,$m228$تشكل مجالس إدارة الشركات القابضة و الشركات التابعة و فق أحكام القانون المرافق خلال ستة أشهر من تاريخ العمل به.
و يتولى رؤساء و أعضاء مجالس الإدارة الحاليون لكل من هيئات القطاع العام وشركاته بحسب الأحوال إدارة الشركات المذكورة و ذلك حتى يتم تشكيل مجالس الإدارة الجديدة لها.$m228$,'ce68988e7e359033e8d2613f1bb8a380',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(3,0,1,$m228$يتولى إدارة الشركة القابضة مجلس إدارة يصدر بتشكيله قرار من الجمعية العامة بناء على اقتراح رئيسها لمدة ثلاث سنوات قابلة للتجديد و يتكون من عدد فردي من الأعضاء لا يقل عن سبعة و لا يزيدج عن أحد عشر و يشكل على الوجه الآتى:
1 - رئيس متفرغ للإدارة.
2 - عدد من الأعضاء لا يقل عن خمسة يختارون من ذوي الخبرة في النواحى الاقتصادية و المالية و الفنية و القانونية و إدارة الأعمال.
3 - ممثل عن الاتحاد العام لنقابات عملا مصر يختاره مجلس إدارة الاتحاد.
و لا يعتبر رئيس و أعضاء مجلس الإدارة من العاملين بالشركة.
و يحدد القرار الصادر بتشكيل المجلس إدارة الأعضاء المتفرغين للإدارة و ما يتقاضاه رئيس مجلس الإدارةو الأعضاء المتفرغون من رواتب مقطوعة كما يحدد هذا القرار مكافأة العضوية و بدل حضور الجلسات الذي يتقضاه كل من رئيس و أعضاء المجلس و يحدد النظام الأساسي للشركة المكافأة السنوية التى يستحقونها بمراعاة نص المادة (34) من هذا القانون.$m228$,'f7bd8629e2f3320d959b332ea25e95e2',DATE '1991-07-20',DATE '2020-09-14','amended',185,2020,$m228$النص قبل تعديل القانون رقم 185 لسنة 2020 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»).$m228$),
(3,0,2,$m228$يتولى إدارة الشركة القابضة مجلس إدارة يصدر بتشكيله قرار من الجمعية العامة بناء على اقتراح رئيسها لمدة ثلاث سنوات قابلة للتجديد على أن يعكس التشكيل حقوق الملكية بالشركة، ويتكون من عدد من الأعضاء يحدده النظام الأساسي لا يقل عن خمسة ولا يزيد على تسعة، ويشكل على الوجه الآتي:
1 - رئيس غير تنفيذي لمجلس إدارة الشركة.
2 - أعضاء يمثلون المساهمين بالشركة وفقا لهيكل ملكية الشركة بمراعاة قواعد التمثيل النسبي، منهم عضو يمثل وزارة المالية يرشحه وزير المالية، وتعينهم الجمعية العامة، دون الإخلال بحق الشخص الاعتباري المساهم في الشركة في تغيير ممثليه خلال مدة المجلس.
3 - ممثل عن الاتحاد النقابي العمالي الأكثر تمثيلا يختاره مجلس إدارة الاتحاد بمراعاة طبيعة نشاط الشركة.
ويجوز أن يتضمن النظام الأساسي للشركة أعضاء مستقلين إضافيين من ذوي الخبرة بمجلس الإدارة لا يزيد عددهم على عضوين تختارهم الجمعية العامة بناء علي ترشيح لوزير المختص.
ولا يعتبر رئيس وأعضاء مجلس الإدارة من العاملين بالشركة.
ويحدد القرار الصادر بتشكيل المجلس العضو المنتدب التنفيذي وغيره من الأعضاء المنتدبين للإدارة.
وتحدد الجمعية العامة سنويا من يتقاضاه كل من رئيس وأعضاء المجلس المشار إليهم من بدلات الحضور والانتقال للجلسات، وكذا ما يتقاضاه رئيس المجلس والأعضاء المنتدبون من رواتب والمكافأة السنوية التي يستحقها مجلس الإدارة بمراعاة نص المادة (24) من هذا القانون، كما تحدد الجمعية العامة المزايا الأخرى للأعضاء المنتدبين للإدارة بما في ذلك التأمين الطبي ووسائل الانتقال.
وفي جميع الأحوال، لا يجوز أن يزيد بدل الحضور والانتقال لرئيس وأعضاء المجلس على الحد الذي يصدر به قرار من رئيس مجلس الوزراء.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'9d8ca178334dff647034bac02f4a95a2',DATE '2020-09-15',NULL,'active',185,2020,$m228$عدلت بالقانون رقم 185 لسنة 2020. تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 15 سبتمبر 2020).$m228$),
(4,-1,1,$m228$ينقل العاملون بكل من هيئات القطاع العام و شركاته الموجودون بالخدمة في تاريخ العمل بهذا القانون إلى الشركات القابضة أو الشركات التابعة لها بذات أوضاعهم الوظيفية وأجورهم وبدالتهم واجازاتهم ومزاياهم النقدية والعينية والتعويضات.
و تستمر معاملة هؤلاء العاملين بجميع الأنظمة والقواعد التى تنظم شئونهم الوظيفية وذلك إلى أن تصدر لوائح أنظمة العاملين بالشركات المنقولين إليها طبقا لأحكام القانون المرافق خلال سنة من التاريخ المذكور.
و يحتفظ العامل المنقول بصفة شخصية بما يحصل عليه من أجور وبدلات و إجازات و مزايا نقدية وعينية و تعويضات و لو كانت تزيد على ما يستحقه طبقا لهذه اللوائح دون أن يؤثر ذلك على ما يستحقه مستقبلا من أية علاوات أو مزايا.$m228$,'c59a794041f42100f664038e8c8a3157',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(4,0,1,$m228$لا يجوز أن يكون رئيسا أو عضوا بمجلس إدارة الشركة من حكم عليه بعقوبة جناية أو بعقوبة مقيدة للحرية في جريمة مخلة بالشرف أو الأمانة أو تفالس أو بعقوبة من العقوبات المنصوص عليها في المواد (49 و50 و51) من هذا القانون.$m228$,'7d4df4734d6b556741e9e20aeaa0e6ab',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(5,-1,1,$m228$مع عدم الإخلال بما ورد في شأنه نص خاص في هذا القانون أو في القانون المرافق لا يسري نظام العاملين بالقطاع العام الصادر بالقانون رقم 48 لسنة 1978 على العاملين بالشركات الخاضعة لحكام القانون المرافق و ذلك اعتبارا من تاريخ العمل باللوائح المشار إليها.$m228$,'1b8c695bfeae0009a13976f49ac9824f',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(5,0,1,$m228$يكون للجمعية العامة العادية للشركة عند مناقشتها لنتائج أعمال الشركة السنوية تغيير رئيس وأعضاء مجلس إدارة الشركة كلهم أو بعضهم أثناء مدة العضوية، وفي حلة تغيير المجلس بأكمله يجوز للجمعية العامة تعيين مفوض لإدارة الشركة بصفة مؤقتة ولمدة لا تجاوز ثلاثة أشهر لحين تشكيل مجلس إدارة جديد طبقا لأحكام هذا القانون.
ويسري حكم هذه الفترة على الشركات التابعة الخاضعة لأحكام هذا القانون.
كما لا يجوز تجديد تعيين رئيس و أعضاء مجلس إدارة الشركة إذا لم تحقق الشركة الأهداف المحددة لها خلال مدة العضوية.
*الفقرة الأولى معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'864a425d8c0f2f39e8300e16ba87babd',DATE '2020-09-15',NULL,'active',185,2020,$m228$الفقرة الأولى معدلة بموجب قانون رقم 185 لسنة 2020. نصها قبل التعديل كما ورد فى المصدر: «يجوز عزل رئيس و أعضاء مجلس إدارة الشركة كلهم أو بعضهم أثناء مدة العضوية بقرار سبب من الجمعية العامة و ذلك طبقا للإجراءات المنصوص علبها في المادة (29) من هذا القانون إذاكان من شأن استمرارهم الإضرار بمصلحة الشركة.» تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 15 سبتمبر 2020).$m228$),
(6,-1,1,$m228$تستمر محاكم مجلس الدولة في نظر الدعاوى و الطعون الآتية التى رفعت إليها إلي أن يتم الفصل فيها بحكم بات و فقا للقواعد المعمول بها حاليا و ذلك دون حاجة لي إجراء آخر.
أولا - الدعاوى التأديبية و طعون الجزاءات التأديبية و غيرها من الدعاوى المتعلقة بالعاملين بالشركات الخاضعة لأحكام هذا القانون متى كانت قد رفعت قبل العمل باللوائح المنصوص عليها في المادة السابقة.
ثانيا - الدعاوي و الطعون الأخري التى تكون تلك الشركات طرفا فيها متى كانت قد رفعت قبل العمل بهذا القانون.$m228$,'32458919648685cfe104b80d19513c27',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(6,0,1,$m228$لمجلس إدارة الشركة مباشرة كل السلطات اللازمة لتصريف أمور الشركة والقيام بكافة الأعمال اللازمة لتحقيق الغرض الذي أنشئت من أجله و ذلك فيما عدا ما تختص به الجمعية العامة للشركة و لمجلس الإدارة في سبيل ذلك على الأخص ما يأتى:
1 - وضع السياسات العامة و تحديد الوسائل اللازمة لتحقيقها.
2 - إدارة محفظة الأوراق المالية للشركة بيعا و شراء مما تتضمنه من أسهم و صكوك تمويل و سندات و أية أدوات و أصول مالية أخرى.
3 - إقتراح تأسيس شركات مساهمة تؤسسها الشركة بمفردها أوبالإشتراك مع الأشخاص الاعتبارية العامة أو الخاصة أو الأفراد.
4 - شراء أسهم شركات المساهمة أو بيعها أو المساهمة في رأس مالها.
5 - القيام بكافة الأعمال اللازمة لتصحيح الهياكل التمويلية و مسار الشركات المتعثرة التابعة لها و تعظيم ربحية هذه الشركات و ترشيد التكلفة.
6 - إقرار مشروع الميزانية و الحسابات الختامية تمهيدا لعرضها على الجمعية العامة للشركة.
7 - و ضع معايير الأداء و تقيمها و فحص التقاير التى تقدم عن سير العمل بالشركة.
8 - اعتماد الهيكل التنظيمى للشركة وو ضع اللوائح الداخلية المتعلقة بالنواحى المالية و الإدارية و الفنية وغيرها.
9 - ما يرى رئيس الجمعية العامة أو رئيس مجلس الإدارة عرضه على المجلس.$m228$,'eae1ef4731df93cd2d19a1699e88c102',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(6,1,1,$m228$يضع مجلس إدارة الشركة القابضة الضوابط الواجب الالتزام بها لقيام الشركة القابضة أو شركاتها التابعة بتأسيس أو المشاركة في تأسيس الشركات الأخرى، ويتم اعتمادها من الوزير المختص، على أن تتضمن هذه الضوابط على الأخص ما يأتي:
1 - وجود جدوى اقتصادية من إنشاء الشركة الجديدة، أو المساهمة فيها.
2 - عدم وجود شركة تابعة أخرى يمكن لها القيام بالنشاط المطلوب تأسيس شركة لممارسته.
3 - أن تكون الجمعية العامة للشركة أو مجلس إدارتها هو السلطة المختص بالموافقة على إنشاء الشركة الجديدة أو المساهمة فيها، وفق لما يحده النظام الأساسي للشركة.
وعلى الشركة القابضة وضع نظام لمتابعة أداء الشركات التي تساهم فيها الشركة القابضة وشركاتها التابعة يتضمن على الأخص التقارير الدورية لمتابعة أداء هذه الشركات والرقابة عليها، وقواعد اختيار ممثلي الشركة القابضة أو التابعة في عضوية مجلس إدارات هذه الشركات، والتأكد من اتباع الإجراءات الواجبة عند التخارج من هذه الشركات، وذلك كله وفقا للقواعد التي يضعها الوزير المختص.
*مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'887b67ca06fbe94f6794f25fb5258a9a',DATE '2020-09-15',NULL,'active',185,2020,$m228$مضافة بموجب قانون رقم 185 لسنة 2020. تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 15 سبتمبر 2020).$m228$),
(7,-1,1,$m228$لا يجوز حرمان الشركات الخاضعة لأحكام هذا القانون من أية مزايا أو تحميلها بأية أعباء تخل بالمساواة بينها و بين شركات المساهمة الخاضعة لأحكام القانون رقم 159 لسنة 1981 المشارإ ليها التى تعمل في ذات النشاط و يلغى البند (1) من المادة السادسة من القانون رقم 66 لسنة 1971 بإنشاء هيئة عامة باسم بنك ناصر الاجتماعي كما تلغى عبارة و في حدود الموازنة النقدية السارية الواردة في الفقرة الأولي من المادة (1) من القانون رقم 118 لسنة 1975 في شأن الاستيراد و التصدير.$m228$,'715959d16c7a0646d080a562f59767f6',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(7,0,1,$m228$يجتمع مجلس الإدارة مرة على الأقل كل شهر بدعوة من رئيسه و في حالة غيابه يندب رئيس الجمعية العامة من بين أعضاء المجلس من يرأس الاجتماع.
و لا يكون انعقاد المجلس صحيحا إلا بحضور أغلبية الأعضاء و تصدر قراراته بأغلبية أصوات الحاضرين وعند التساوى يرجح الجانب الذي منه الرئيس.
وللمجلس أن يدعو لحضور اجتماعاته من يرى الإستعانة بهم من ذوى الخبرة من العاملين بالشركة أو غيرهم دون ان يكون لهم صوت معدود فيما يتخذه المجلس من قرارات.
و يجوز للمجلس أن يشكل من بين أعضائه لجنة أو لجانا يعهد إليها ببعض إختصاصاته كما يجوز له أن يعهد إلي رئيس مجلس الإدارة أو أحد المديرين في القيام بمهمة محددة على أن يعرض على المجلس تقريرا بما قام به من أعمال.$m228$,'e387433c2f0b253a928bfd0d46113fb1',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(8,-1,1,$m228$يصدر رئيس الجمهورية قرار بتحديد الوزير المختص (*) في تطبيق أحكام هذا القانون وعليه أن يقدم إلي مجلس الوزراء تقارير دورية و فقا لما تحدده اللائحة التنفيذية عن نتائج أعمال الشركات الخاضعة لأحكام هذاالقانون.
(*) انظر قرار رئيس جمهورية مصر العربية رقم 296 لسنة 1991 ص 115 من هذاالكتاب$m228$,'ab7dc66334b814eb67de063c086fa6f9',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(8,0,1,$m228$يمثل رئيس مجلس الإدارة الشركة أمام القضاة و في صالتها بالغير و يختص بما يأتى:
1 - تنفيذ قرارات مجلس الإدارة.
2 - إدارة الشركة و تصريف شئونها.
و يباشر رئيس مجلس الإدارة الإختصاصات المقررة في القوانين واللوائح لعضو مجلس الإدارة المنتدب و يقوم بواجباته و له أن يفوض واحدا أو أكثرمن أعضاء مجلس الإدارة في بعض إختصاصاته.$m228$,'ed6ab0e352ac9a7600eb773fc67ff2e5',DATE '1991-07-20',DATE '2020-09-14','amended',185,2020,$m228$النص قبل تعديل القانون رقم 185 لسنة 2020 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»).$m228$),
(8,0,2,$m228$يمثل الشركة أمام القضاء وفي صالتها بالغير رئيس مجلس الإدارة أو العضو المنتدب التنفيذي بحسب النظام الأساسي للشركة، ويختص العضو المنتدب التنفيذي بما يأتي:
1 - تنفيذ قرارات مجلس الإدارة.
2 - إدارة الشركة وتصريف شئونها.
وله أن يفوض واحدا أو أكثر من أعضاء مجلس الإدارة في بعض اختصاصاته.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'49e1723657e8cc8812e45d9e229b8b9e',DATE '2020-09-15',NULL,'active',185,2020,$m228$عدلت بالقانون رقم 185 لسنة 2020. تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 15 سبتمبر 2020).$m228$),
(9,-1,1,$m228$يجوز بقرار من رئيس الجمهورية بعد موافقة مجلس الوزراء تحويل إحدي الهيئات الاقتصادية أو المؤسسات العامة أو شركات القطاع العام المقرر لها أنظمة خاصة إلي شركة قابضة أو شركة تابعة تخضع لحكام هذا القانون.$m228$,'a5170f1b0c8499933bfbcda3978c3878',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(9,0,1,$m228$تتكون الجمعية العامة للشركة على النحو التالى:
1 - الوزير المختص رئيسا.
2 - أعضاء من ذوى الخبرة في مجال الأنشطة التى تقوم بها الشركات التابعة للشركة القابضةال يقل عددهم عن إثنى عشر و لا يزيد على أربعة عشر من بينهم ممثل واحد على الأقل يرشحه الاتحاد العام لنقابات عملا مصر يصدر بإختيارهم قرار من رئيس مجلس الوزراءو يحدد القرار ما يتقاضونه من بدل الحضور وفقا للقواعد التى تحددها اللائحة التنفيذية.
و يحضر اجتماعات الجمعية العامة رئيس و أعضاء مجلس إدارة الشركة و مراقبو الحسابات بالجهاز المركزى للمحاسبات دون ان يكون لهم صوت معدود.
وتصدر قرارات الجمعية العامة بأغلبية أصوات الحاضرين فيما عدا الأحوال التى تتطلب فيها اللائحة التنفيذية أو النظام الأساسي للشركة أغلبية خاصة.
و تبين اللائحة التنفيذية شروط صحة انعقاد الجمعية العامة و نظام التصويت على المسائل المعروضة عليها بحسب ما إذا كانت الجمعية العامة منعقدة في اجتماع عادى أو غير عادى.$m228$,'c54e4bbcc954bf0eb3780a34c603bb34',DATE '1991-07-20',DATE '2020-09-14','amended',185,2020,$m228$النص قبل تعديل القانون رقم 185 لسنة 2020 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»).$m228$),
(9,0,2,$m228$تتكون الجمعية العامة للشركة على النحو الآتي:
1 - الوزير المختص رئيسا.
2 - أعضاء من ذوي الخبرة في مجال الأنشطة التي تقوم بها الشركة القابضة وشركاتها التابعة لا يقل عددهم عن اثني عشر ولا يزيد على أربعة عشرة من بينهم ممثل واحد على الأقل يرشحه الاتحاد النقابي العمالي الأكثر تمثيلا وممثل عن وزارة المالية برشحه وزير المالية يصدر باختيارهم قرار من رئيس مجلس الوزراء، ويحدد القرار ما يتقاضونه من بدل الحضور والانتقال وفقا للقواعد التي تحددها اللائحة التنفيذية لهذا القانون.
ويحضر اجتماعات الجمعية العامة رئيس وأعضاء مجلس إدارة الشركة، ومراقبو الحسابات بالجهاز المركزي للمحاسبات، ومراقب الحسابات المعين من الجمعية العامة للشركة إن وجد، دون أن يكون لهم صوت معدود.ويجوز للوزير المختص تفويض غيره في حضور الجمعية العامة.
وتصدر قرارات الجمعية العامة بأغلبية أصوات الحاضرين بالاجتماع فيما عدا الأحوال التي تتطلب فيها اللائحة التنفيذية لهذا القانون أو النظام الأساسي للشركة أغلبية خاصة.
وتبين اللائحة التنفيذية لهذا القانون شروط صحة انعقاد الجمعية العامة ونظام التصويت على المسائل المعروضة عليها بحسب ما إذا كانت الجمعية العامة منعقدة في اجتماع عادي أو غير عادي.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'561e2972b4edf07dc42e4488e0571ded',DATE '2020-09-15',NULL,'active',185,2020,$m228$عدلت بالقانون رقم 185 لسنة 2020. تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 15 سبتمبر 2020).$m228$),
(10,-1,1,$m228$لا تخل أحكام المادة الثامنة من هذا القانون بالإختصاصات والسلطات الإدارية والتنفيذية المقررة للوزراء بمقتضى القوانين و اللوائح والقرارات الجمهورية.$m228$,'247ba8457135641e589c6ee488df15e3',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(10,0,1,$m228$مع مراعاة أحكام هذا القانون و لائحته التنفيذية و النظام الساسي للشركة تختص الجمعية العادية العادية بما يأتى:
(أ) التصديق على تقرير مجلس الإدارة عن نشاط الشركة و النظر في إخلاء المجلس من المسئولية عن الفترة المقدم عنها التقرير.
(ب) التصديق على الميزانية والحسابات الختامية للشركة.
(ج) الموافقة على استمرار رئيس و أعضاء مجلس الإدارة لمدة تالية أو عزلهم.
ويكون التصويت على ذلك بطريق الاقتراع السري.
(د) الموافقة على توزيع الأرباح.
(ه) كل ما يرى رئيس الجمعية العامة أو مجلس الإدارة عرضه عليها.
و لا يجوز التصرف بالبيع في أصل من خطوط الإنتاج الرئيسية إلا بعد موافقة الجمعية العامة و طبقا للقواعد التى تحددها اللائحة التنفيذية.$m228$,'2d0f00bcfd677d2455768e1303877122',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(11,-1,1,$m228$يختص مجلس الدولة دون غيره بمراجعة نموذج العقد الأبتدائى و نماذج النظام الأساسي للشركات الخاضعة لأحكام هذا القانون.
ولشركات المشارإليها أن تطلب إلي مجلس الدولة عن طريق الوزير المختص إباء الرأي مسببا في المسائل المتعلقة بشئون العاملين فيها أو أعضاء مجلس إدارتها أو بغير ذلك من المسائل التى تتعلق بأي شأن آخر من شئونها.$m228$,'5f649e7ddad0042f3804625dc2e5824a',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(11,0,1,$m228$لا يجوز تعديل نظام الشركة إلا بعد موافقة الجمعية العامة غير العادية وفقا لأحكام اللائحة التنفيذية.$m228$,'6e4eb2c809cec6129f7907faeec623a0',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(12,-1,1,$m228$يصدر رئيس مجلس الوزراء اللائحة التنفيذية للقانون المرافق خلال ثلاثة أشهر من تاريخ العمل بهذا القانون(*).
كما يصدر نموذج العقد الأبتدائي و نموذج النظام الأساسي للشركات الخاضعة لأحكام هذا القانون و ذلك خلال ستة أشهر من تاريخ العمل باللائحة التنفيذية (-) و يجوز أن تتعدد نماذج النظم الأساسية للشركات بحسب طبيعة أنشطتها.
(*) صدر قرار رئيس مجلس الوزراء رقم 1590 لسنة 1991 بغصدار اللائحة التنفيذية المشار إليها و نشر بالجريدة الرسمية –عدد رقم 44 تابع في 31/10/1991 و أعدبه كتابة و يرجع إليه إذا لزم الأمر.
(-) صدر قرار رئيس مجلس الوزراء رقم 1900 لسنة 1991 بإصدار نماذج العقود الإبتدائية و الأنظمة الأساسية لشركات قطاع الأعمال العام ونشر بالجريدة الرسمية –عدد(2 تابع) في 1992/9/1 و أعد به كتابة إذا لزم الأمر.
()-$m228$,'85fe4a922a7f197829f0bc7bde52adfb',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(12,0,1,$m228$يحدد النظام الأساسي بداية ونهاية السنة المالية للشركة.
و تعتبر أموال الشركةمن الأموال المملوكة للدولة ملكية خاصة و تودع الشركة مواردها بالنقد المحلي و الأجنبي في حساب مصرفي بالبنك المركزى أو أحد البنوك التجارية.$m228$,'e9f6b94c292f077f2c52a5129738c3ac',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(13,-1,1,$m228$ينشر هذا القانون في الجريدة الرسمية، و يعمل به بعد ثلاثين يوما من تاريخ نشره.
يبصم هذا القانون بخاتم الدولة، و ينفذ كقانون من قوانينها.
صدر برياسة الجمهورية في 7 ذي الحجة سنة 1411. (19 يونية سنة 1991 م) حسنى مبارك$m228$,'87a7dddee2f5a97c07b384ab5fd8379b',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(13,0,1,$m228$تعد الشركة القابضة قوائم مالية مجمعة تعرض اصول و التزامات و حقوق المساهمين و إيردات و مصروفات و استخدامات الشركة القابضة و الشركات التابعة لها وفقا للأوضاع و الشروط و البيانات التى تحددها اللائحة التنفيذية$m228$,'9b27cceebf26517721d65c75af9eabf1',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(14,0,1,$m228$تحدد الأرباح الصافية للشركة و يتم توزيعها بقرار من الجمعية العامة طبقا لأحكام هذا القانون ولائحته التنفيذية.
و يؤول نصيب الدولة في هذه الأرباح إلي الخزانة العامة.
(*) ولوزير المالية أو من يفوضه الخصم من خلال البنك المركزى المصري مستحقات الدولة في أرباح الشركات القابضة طبقا لحساب التوزيع المصادق عليه من الجمعية العامة على حسابات هذه الشركات بالجهاز المصرفي و ذلك في حالة تخلفها عن السداد في موعد غايتها ستة أشهر من قرار الجمعية العامة بتوزيع الأرباح.
(*) الفقرة الأخيرة من المادة 14 أضيفت بالقانون رقم 149 لسنة 2001 الصادر بالجريدة الرسمية –العدد رقم 25 مكرر (أ) الصادر في 2001/6/24$m228$,'fdea98835cfb20fce64262abdf1e4820',DATE '2001-06-24',NULL,'active',149,2001,$m228$الفقرة الأخيرة أضيفت بالقانون رقم 149 لسنة 2001 (الجريدة الرسمية العدد 25 مكرر (أ) فى 24/6/2001) بحسب حاشية المصدر؛ تاريخ النفاذ مسجل بتاريخ الجريدة.$m228$),
(15,0,1,$m228$يتولى الجهاز المركزى للمحاسبات مراقبة حسابات الشركة وتقييم أدائها طبقا لقانونه.
ويجوز للجمعية العامة للشركة تعيين مرقب حسابات أخر للشركة، بالإضافة إلى مراقب الجهاز المركزي للمحاسبات من مراقبي الحسابات المقيدين بسجلات الهيئة العامة الرقابة المالية، على أن تحدد الجمعية العامة أتعابه.
*الفقرة الثانية مضافة بموجب قانون رقم 185 لسنة 2020.$m228$,'eaf20b74930c47010c1be3970c05a485',DATE '2020-09-15',NULL,'active',185,2020,$m228$الفقرة الثانية مضافة بموجب قانون رقم 185 لسنة 2020. تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 15 سبتمبر 2020).$m228$),
(16,0,1,$m228$مع عدم الإخلال بحكم المادة (39 مكرر) من هذا القانون، تعتبر شركة تابعة في تطبيق أحكام هذا القانون الشركة التي يكون لأحدى الشركات القابضة أكثر من (50%) من رأسمالها أو من حقوق التصويت بها.
فإذا اشترك في هذه النسبة أكثر من شركة من الشركات القابضة أو الأشخاص الاعتبارية العامة أو بنوك القطاع العام يصدر رئيس مجلس الوزراء قرارا بتحديد الشركة القابضة التى تتبعها هذه الشركة.
و تتخذ الشركة التابعة شكل شركة المساهمة و تثبت لها الشخصية الاعتبارية من تاريخ قيدها في السجل التجاري.
*الفقرة الأولى معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'839ed6f9c4c6a7f819819a3ee2585f58',DATE '2020-09-15',NULL,'active',185,2020,$m228$الفقرة الأولى معدلة بموجب قانون رقم 185 لسنة 2020. نصها قبل التعديل كما ورد فى المصدر: «تعتبر شركة تابعة في تطبيق أحكام هذا القانون الشركة التى يكون لاحدى الشركات القابضة 51% من رأس مالها على الأقل.» تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 15 سبتمبر 2020).$m228$),
(17,0,1,$m228$يصدر بتأسيس الشركة التابعة قرار من الوزير المختص بناء على اقتراح مجلس إدارة الشركة القابضة و ينشر هذا القرار مرفقا به النظام الأساسي على نفقة الشركة في الوقائع المصرية و تقيد الشركة في السجل التجارى.$m228$,'1555e1e2189786176b208ec2d329bf36',DATE '1991-07-20',NULL,'active',NULL,NULL,NULL),
(18,0,1,$m228$يقسم رأس مال الشركة إلي أسهم اسمية متساوية القيمة.
و يحدد النظام الأساسي القيمة الاسمية للسهم بحيث لا تقل عن خمسة جنيهات ولا تزيد على مائة جنيه، و لا يسرى هذا الحكم على الشركات التابعة التى حلت بمقتضى أحكام هذا القانون محل الشركات التى كانت تشرف عليها هيئات القطاع العام.
و يكون السهم غير قابل للتجزئة و لا يجوز إصداره بأقل من قيمته الاسمية.
كما لا يجوز إصداره بقيمة أعلى إلا فى الأحوال وبالشروط التى تحددها اللائحة التنفيذية على أن تضاف هذه الزيادة الى الاحتياطى.
و لا يجوز بأي حال أن تجاوز مصاريف الاصدار الحد الذى يصدر به قرار من الهيئة العامة لسوق المال.
وتنظم اللائحة التنفيذية ما تتضمنه شهادات الأسهم من بيانات و كيفية استبدال الشهادات المفقودة أو التالفة و ما يتبع بالنسبة لهذه الشهادات عند تعديل نظام الشركة.$m228$,'ffd9383144830ecaa6bbc91929294c5e',DATE '1991-07-20',DATE '2020-09-14','amended',185,2020,$m228$النص قبل تعديل القانون رقم 185 لسنة 2020 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»).$m228$),
(18,0,2,$m228$يقسم رأسمال الشركة إلى أسهم اسمية متساوية القيمة.
ويحدد النظام الأساسي القيمة الاسمية للسهم بما لا يقل عن الحد الأدنى وفق لقانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 ويكون للسهم غير قابل للتجزئة، ولا يجوز إصداره بأقل من قيمته الأسمية، كما لا يجوز إصداره بقيمة أعلى إلا في الأحوال وبالشروط المبينة في قانون سوق رأس المال المشار إليه ولائحته التنفيذية، على أن تضاف هذه الزيادة إلى الاحتياطي.
ولا يجوز بأي حال أن تجاوز مصاريف الإصدار الحد الذي يصدر به قرار من الهيئة العامة للرقابة المالية.
ويتم إيداع أسهم الشركة لدى إحدى الشركات أو الجهات المرخص لها بنشاط الإيداع والقيد المركزي للأوراق والأدوات المالية.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'a841748e3c940124acdcf1e9a01dc2ac',DATE '2020-09-15',NULL,'active',185,2020,$m228$عدلت بالقانون رقم 185 لسنة 2020. تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 15 سبتمبر 2020).$m228$),
(19,0,1,$m228$إذا دخل في تكوين رأس مال الشركة عند تأسيسها او عند زيادة رأس مالها حصص عينية مادية أو معنوية وجب على المؤسسين أو مجلس الادارة بحسب الأحوال أن يطلبوا الى الوزير المختص التحقق ما اذا كانت هذه الح قد قدرت تقديرا صحيحا.
وتتولى التحقق من صحة هذا التقدير لجنة تشكل بقرار من الوزير المختص برئاسة مستشار بإحدي الهيئات القضائية يختاره رئيسها و عضوية أربعة على الأكثر من ذوى الخبرة الإقتصادية و المحاسبية و القانونية و الفنية و ممثل عن المؤسسين أو المساهمين يختاره مجلس ادارة الشركة القابضة أو مجلس ادارة الشركة التابعة بحسب الأحوال، وممثل عن كل من وزارة المالية والجهاز المركزى للمحاسبات.
وتقدم اللجنة تقريرها إلي الوزير المختص في مدة أقصاها ستون يوما من تاريخ إحالة الأوراق إليها و لا يصبح التقدير نهائيا إلا بعد إعتماده منه.$m228$,'07adfa11a7325244a56408ff97d63265',DATE '1991-07-20',DATE '2020-09-14','amended',185,2020,$m228$النص قبل تعديل القانون رقم 185 لسنة 2020 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»).$m228$),
(19,0,2,$m228$تشكل بقرار من الوزير المختص لجنة أو أكثر برئاسة أحد أعضاء الجهات أو الهيئات القضائية بدرجة مستشار على الأقل تختاره جهة عمله، وعضوية ممثل عن كل من وزارة المالية، والجهاز المركزي للمحاسبات، وممثل عن المؤسسين أو المساهمين يختاره مجلس إدارة الشركة القابضة أو التابعة بحسب الأحوال، وأربعة على الأكثر من ذوي الخبرة الاقتصادية والمحاسبية والقانونية والفنية يختارهم الوزير المختص.
وتتولى اللجنة المشار إليها بالفقرة السابقة التحقق من صحة تقييم الأصول الأتية:
1 - الحصص العينية المالية والمعنوية الداخلة في رأسمال الشركات الخاضعة لأحكام هذا القانون عند التأسيس أو الاندماج أو عند زيادة رأس المال.
2 - الأسهم والحصص التي تملكها الدولة في الشركات القابضة.
3 - الأسهم والحصص التي تمتلكها الشركة القابضة في شركاتها التابعة او تمتلكها في غيرها من الشركات الأخرى قبل التصرف فيها.
4 - أسهم الشركات الخاضعة لأحكام هذا القانون في حالات مبادلتها بأسهم في شركات أخرى.
5 - الأصول العقارية غير المستغلة التي تقرر الشركة التصرف فيها.
وعلى اللجنة تقديم تقريرها إلى الوزير المختص أو الشركة بحسب الأحوال في مدة أقصاها ثلاثون يوما من تاريخ إحالة الأوراق إليها، وتحدد اللائحة التنفيذية لهذا القانون القواعد والإجراءات الواجب الالتزام بها عند القيام بأعمال التقييم واعتماده بمراعاة معايير التقييم المالي للمنشآت والمعايير المصرية للتقييم العقاري.
*معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'b57b075fee25d380683a151a66ebbe7c',DATE '2020-09-15',NULL,'active',185,2020,$m228$عدلت بالقانون رقم 185 لسنة 2020. تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 15 سبتمبر 2020).$m228$),
(20,0,1,$m228$تكون أسهم الشركة قابلة للتداول فور إصدارها، ويكون تداول او نقل ملكية أسهم الشركات الخاضعة لهذا القانون بمراعاة أحكام هذا القانون ولائحته التنفيذية والقواعد المطبقة بالبورصات المصرية.
و يجوز تداول حصص التأسيس و الأسهم التى تعطى مقابل حصة عينية و الأسهم التى يكتتب فيها مؤسسو الشركة من تاريخ قيدها في السجل التجارى.
*الفقرة الأولى معدلة بموجب قانون رقم 185 لسنة 2020.$m228$,'0d73dc1329fd1f1f0f8454307376d974',DATE '2020-09-15',NULL,'active',185,2020,$m228$الفقرة الأولى معدلة بموجب قانون رقم 185 لسنة 2020. نصها قبل التعديل كما ورد فى المصدر: «تكون أسهم الشركة قابلة للتدوال طبقا للأحكام المبينة في اللائحة العامة لبورصات الأوراق المالية الصادرة بالقانون رقم 161 لسنة 1957 و قانون شركات المساهمة و شركات التوصية بالأسهم و الشركات ذات المسئولية المحدودة الصادر بالقانون رقم 159 لسنة 1981.» تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 15 سبتمبر 2020).$m228$),
(21,0,1,$m228$مع مراعاة أحكام المادة (4) من هذا القانون يتولى إدارة الشركة التى يملك رأس مالها بأكمله شركة قابضة بمفردها أو بالأشتراك مع شركات قابضة اخري أو أشخاص عامة أو بنوك القطاع العام مجلس إدارة يعين لمدة ثلاث سنوات قابلة للتجديد.
و يجتمع مجلس الإدارة مرة على الأقل كل شهر بدعوة من رئيسه و في حالة غيابه يندب رئيس الجمعية العامة من بين أعضاء المجلس من يرأس الاجتماع.
و يكون مجلس الإدارة من عدد فردي من الأعضاء لا يقل عن خمسة و لا يزيد على تسعة بما فيهم رئيس المجلس على النحو التالي:
(أ) رئيس غير متفرغ من ذوي الخبرة تعينه الجمعية العامة للشركة بناء على ترشيح مجلس إدارة الشركة القابضة.
(ب) أعضاء غير متفرغين يعينهم مجلس إدارة السركة القابضة من ذوي الخبرة يمثلون الجهات المساهمة في الشركة ويكون عددهم نصف عدد أعضاء المجلس.
(ج) عدد من الأعضاء مماثل لعدد الأعضاء من ذوى الخبرة يتم انتخابهم من العاملين بالشركة طبقا لأحكام القانون المنظم لذلك.
(د) رئيس اللجنة النقابية و لا يكون له صوت معدود و في حالة تعدد اللجان النقابية في الشركة تختار النقابة العامة أحد رؤساء هذه اللجان.
و تحدد الجمعية ما يتقاضاه كل من رئيس و أعضاء المجلس المشار إليهم في البندين (أ، ب) من الفقرة السابقة من مكافآت العضوية كما يحدد النظام الأساسي للشركة المكافأة السنوية التى يستحقونها بمراعاة نص المادة (34) من هذا القانون (*).
و تحدد الجمعية العامة بدل حضور الجلسات الذي يتقاضاه أعضاء المجلس و ما يستحقه أعضاؤه المنتخبون من مكافأة سنوية بما لا يجاوز الأجر السنوى الأساسى (-)
و يختار مجلس إدارة الشركة القابضة من بين الأعضاء المعينين المنصوص عليهم في البند (ب) عضوا منتدبا أو أكثر يتفرغ للإدارة و يحدد ما يتقاضاه من راتب مقطوع بالإضافة إلي ما يستحقه من مبالغ طبقا للفقرة الرابعة من هذه المادة.
و يحدد المجلس من يحل محل العضو المنتدب في حالة غيابه أو خلو منصبه أو عزله.
وللمجلس أن يعهد إلي رئيسه بأعمال العضو المنتدب على أن يفرغ للإدارة و في هذه الحالة يحدد له ما يتقاضاه من راتب مقطوع بالإضافة إلي ما يستحقه من مبالغ و فقا للفقرة الرابعة من هذه المادة.
(*) الفقرة الرابعة من المادة (21) حكم بعدم دستوريتها بالقضية رقم 180 لسنة 20 قضائية دستورية الجريدة الرسمية العدد (20 تابع) في 3/1/2000
(-) الفقرة الخامسة من المادة (21) حكم بعدم دستوريتها بالقضية رقم 30 لسنة 16 قضائية دستورية (الجريدة الرسمية العدد /16 في 18/4/1996)$m228$,'61017e767768e6ded079f151f61504b2',DATE '1991-07-20',DATE '2020-09-14','amended',185,2020,$m228$النص قبل تعديل القانون رقم 185 لسنة 2020 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»).$m228$),
(21,0,2,$m228$مع مراعاة حكم المادة (4) من هذا القانون، يتولى إدارة الشركة التابعة مجلس إدارة تختاره الجمعية العامة لمدة ثلاث سنوات قابلة للتجديد.
ويجتمع مجلس الإدارة مرة على الأقل كل شهر بدعوة من رئيسه، وفي حالة غيابه يندب رئيس الجمعية العامة من بين أعضاء المجلس من يرأس الاجتماع.
ويتكون مجلس الإدارة من عدد من الأعضاء يحدده النظام الأساسي لا يقل عن خمسة ولا يزيد على تسعة بمن فيهم رئيس المجلس على النحو الآتي:
(أ) رئيس غير تنفيذي، تختاره للجمعية العامة للشركة بناء على ترشيح مجلس إدارة الشركة القابضة.
(ب) أعضاء يمثلون المساهمين بالشركة وفقا لهيكل ملكية الشركة بمراعاة قواعد التمثيل النسبي، تعينهم الجمعية العامة مع عدم الإخلال بحق الشخص الاعتباري المساهم في الشركة في تغيير ممثليه خلال مدة المجلس.
(ج) ممثل لو اثنان من العاملين بالشركة بحسب عدد أعضاء مجلس الإدارة، يتم انتخابه أو انتخابهما طبقا لأحكام للقانون المنظم لذلك.
ويجوز أن يتضمن النظام الأساسي للشركة أعضاء مستقلين إضافيين من ذوي الخبرة بمجلس الإدارة لا يزيد عددهم على عضوين تختارهما الجمعية العامة بناء على ترشيح مجلس إدارة الشركة القابضة.
وتحدد الجمعية العامة سنويا ما يتقاضاه كل من رئيس وأعضاء المجلس المشار إليهم من بدلات الحضور والانتقال للجلسات و المكافأة السنوية التي يستحقها مجلس الإدارة بمراعاة نص المادة (34) من هذا القانون، كما تحدد الجمعية العامة المزايا الأخرى للأعضاء المنتدبين بما في ذلك التأمين الطبي ووسائل الانتقال.
وفي جميع الأحوال، لا يجوز أن يزيد بدل الحضور والانتقال لرئيس وأعضاء المجلس عن الحد الذي يصدر به قرار من رئيس مجلس الوزراء.
ويختار مجلس إدارة الشركة من بين أعضاء المجلس العضو المكتب التنفيذي وغيره من الأعضاء المنتدبين للإدارة ويحدد ما يتقاضونه من راتب بالإضافة إلى ما يستحقونه من مبالغ طبقا للفقرة الخامسة من هذه المادة.
ويحدد المجلس من يحل محل العضو المنتدب في حالة غيابه لو خلو منصبه أو تغييره.
